import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { ArrowUpRight, X, Download, FileText } from 'lucide-react';
import { createPortal } from 'react-dom';
import { PROJECTS_DATA } from '../constants';
import { Project } from '../types';

const Projects: React.FC = () => {
  const [hoveredProject, setHoveredProject] = useState<Project | null>(null);
  const [mousePos, setMousePos] = useState({ x: 0, y: 0 });
  const [docUrl, setDocUrl] = useState<string | null>(null);

  const handleMouseMove = (e: React.MouseEvent) => {
    setMousePos({ x: e.clientX + 20, y: e.clientY + 20 });
  };

  const handleProjectClick = (project: Project) => {
    // Specific logic for the Research Project to open in Modal
    if (project.id === 'facial-gans') {
      // Convert view link to preview link for embedding
      // Input: https://drive.google.com/file/d/1NW_FX6_oFa5qWKX-K3pbu4UtVtElPS5X/view?usp=sharing
      // Output: https://drive.google.com/file/d/1NW_FX6_oFa5qWKX-K3pbu4UtVtElPS5X/preview
      const embedUrl = "https://drive.google.com/file/d/1NW_FX6_oFa5qWKX-K3pbu4UtVtElPS5X/preview";
      setDocUrl(embedUrl);
    } else if (project.repoUrl || project.demoUrl) {
      window.open(project.repoUrl || project.demoUrl, '_blank');
    }
  };

  return (
    <section id="projects" className="bg-bg relative">
      <div className="grid grid-cols-1 md:grid-cols-4 border-b border-fg">
        <div className="p-8 border-b md:border-b-0 md:border-r border-fg flex items-center">
            <h2 className="text-3xl font-serif">Selected Works</h2>
        </div>
        <div className="md:col-span-3 p-8 flex items-center justify-between">
             <span className="font-mono text-xs uppercase tracking-widest opacity-50">Index 01 — 03</span>
             <span className="font-mono text-xs uppercase tracking-widest opacity-50">Archived 2024</span>
        </div>
      </div>

      <div className="flex flex-col">
        {PROJECTS_DATA.map((project, index) => {
          const paddedIndex = `0${index + 1}`;

          return (
            <motion.div
              key={project.id}
              onClick={() => handleProjectClick(project)}
              onMouseEnter={() => setHoveredProject(project)}
              onMouseLeave={() => setHoveredProject(null)}
              onMouseMove={handleMouseMove}
              initial={{ opacity: 0 }}
              whileInView={{ opacity: 1 }}
              viewport={{ once: true }}
              className="group grid grid-cols-1 md:grid-cols-12 border-b border-fg min-h-[120px] transition-colors hover:bg-fg hover:text-bg cursor-pointer relative"
            >
              {/* Index Column */}
              <div className="md:col-span-1 p-6 md:p-8 font-mono text-sm opacity-50 border-b md:border-b-0 md:border-r border-fg group-hover:border-bg group-hover:text-bg">
                {paddedIndex}
              </div>

              {/* Title Column */}
              <div className="md:col-span-4 p-6 md:p-8 flex flex-col justify-center border-b md:border-b-0 md:border-r border-fg group-hover:border-bg">
                 <h3 className="text-3xl md:text-4xl font-serif group-hover:italic transition-all flex items-center gap-2">
                    {project.title}
                    {project.id === 'facial-gans' && <FileText size={18} className="opacity-50" />}
                 </h3>
              </div>

              {/* Description/Tags Column */}
              <div className="md:col-span-6 p-6 md:p-8 flex flex-col justify-center gap-4 border-b md:border-b-0 md:border-r border-fg group-hover:border-bg">
                 <p className="font-mono text-sm leading-relaxed opacity-80 group-hover:text-bg/90">
                     {project.description}
                 </p>
                 <div className="flex flex-wrap gap-2">
                     {project.tags.slice(0, 3).map(tag => (
                         <span key={tag} className="text-[10px] font-mono border border-current px-1 uppercase group-hover:border-bg">
                             {tag}
                         </span>
                     ))}
                 </div>
              </div>

              {/* Link Column */}
              <div className="md:col-span-1 p-6 md:p-8 flex items-center justify-center group-hover:border-bg">
                  <ArrowUpRight className="w-8 h-8 md:w-6 md:h-6 transition-transform group-hover:-translate-y-1 group-hover:translate-x-1" />
              </div>
            </motion.div>
          );
        })}
      </div>

      {/* Hover Preview Tooltip (Portal) */}
      <AnimatePresence>
        {hoveredProject && hoveredProject.imageUrl && createPortal(
          <motion.div
            initial={{ opacity: 0, scale: 0.9, y: 10 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.9 }}
            transition={{ duration: 0.15 }}
            style={{ 
              position: 'fixed', 
              left: mousePos.x, 
              top: mousePos.y,
              zIndex: 9999,
              pointerEvents: 'none'
            }}
            className="w-80 bg-bg border border-fg shadow-[12px_12px_0px_0px_var(--fg)] p-1 hidden md:block"
          >
             <div className="aspect-video w-full overflow-hidden bg-fg/10 mb-1">
                <img 
                   src={hoveredProject.imageUrl} 
                   alt={hoveredProject.title} 
                   className="w-full h-full object-cover grayscale"
                />
             </div>
             <div className="bg-fg text-bg px-2 py-1 text-[10px] font-mono uppercase font-bold flex justify-between">
                <span>PROJECT PREVIEW</span>
                <span>{hoveredProject.id === 'facial-gans' ? 'PDF DOCUMENT' : 'APP INTERFACE'}</span>
             </div>
          </motion.div>,
          document.body
        )}
      </AnimatePresence>

      {/* Document Viewer Modal */}
      <AnimatePresence>
        {docUrl && (
          <div className="fixed inset-0 z-[100] bg-bg/95 backdrop-blur-sm flex items-center justify-center p-4">
             <motion.div 
               initial={{ opacity: 0, y: 20 }}
               animate={{ opacity: 1, y: 0 }}
               exit={{ opacity: 0, y: 20 }}
               className="w-full max-w-6xl h-[90vh] bg-zinc-200 border border-fg shadow-[20px_20px_0px_0px_var(--fg)] flex flex-col"
             >
