                <div className="flex justify-between items-center p-4 border-b border-fg bg-fg text-bg shrink-0">
                    <div className="flex items-center gap-3">
                        <FileText size={18} />
                        <span className="font-mono text-sm uppercase font-bold tracking-widest">Research_Thesis.pdf</span>
                    </div>
                    <div className="flex items-center gap-4">
                        <a 
                            href="https://drive.google.com/file/d/1NW_FX6_oFa5qWKX-K3pbu4UtVtElPS5X/view?usp=sharing" 
                            target="_blank"
                            rel="noopener noreferrer"
                            className="flex items-center gap-2 hover:bg-bg hover:text-fg px-3 py-1 rounded transition-colors font-mono text-xs font-bold"
                        >
                            <Download size={14} /> OPEN EXTERNAL
                        </a>
                        <button 
                            onClick={() => setDocUrl(null)} 
                            className="hover:bg-bg hover:text-fg p-1 rounded transition-colors"
                        >
                            <X size={20} />
                        </button>
                    </div>
                </div>

                {/* Iframe Viewer */}
                <div className="flex-1 bg-zinc-800 relative">
                    <iframe 
                        src={docUrl}
                        className="w-full h-full border-none"
                        title="Document Viewer"
                        allow="autoplay"
                    ></iframe>
                </div>
             </motion.div>
          </div>
        )}
      </AnimatePresence>
    </section>
  );
};

export default Projects;

