import React, { useState, useRef } from 'react';
import { motion, AnimatePresence, useScroll, useSpring, useTransform } from 'framer-motion';
import { X, Briefcase, GraduationCap, ChevronRight, MousePointerClick, Zap } from 'lucide-react';
import { EXPERIENCE_DATA } from '../constants';
import { Experience as ExperienceType } from '../types';

const Experience: React.FC = () => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [selectedExp, setSelectedExp] = useState<ExperienceType | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // Scroll tracking for the timeline line
  const { scrollYProgress } = useScroll({
    target: containerRef,
    offset: ["start center", "end center"]
  });

  const scaleY = useSpring(scrollYProgress, {
    stiffness: 100,
    damping: 30,
    restDelta: 0.001
  });

  const handleOpen = () => {
    if ('vibrate' in navigator) navigator.vibrate(15);
    setIsExpanded(true);
  };

  const handlePointClick = (exp: ExperienceType) => {
    if ('vibrate' in navigator) navigator.vibrate(10);
    setSelectedExp(exp);
  };

  return (
    <section id="experience" className="bg-bg relative overflow-hidden transition-all duration-700">
      <AnimatePresence mode="wait">
        {!isExpanded ? (
          /* --- INITIAL BOX VIEW --- */
          <motion.div 
            key="box-view"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0, scale: 0.95, filter: 'blur(10px)' }}
            onClick={handleOpen}
            className="group cursor-pointer p-12 md:p-24 flex flex-col items-center justify-center text-center hover:bg-fg/5 transition-colors min-h-[400px]"
          >
            <motion.div 
              animate={{ y: [0, -10, 0] }}
              transition={{ duration: 4, repeat: Infinity, ease: "easeInOut" }}
              className="mb-8 p-6 border border-fg relative"
            >
              <Zap className="text-fg" size={48} />
              <div className="absolute -top-1 -right-1 w-2 h-2 bg-fg"></div>
              <div className="absolute -bottom-1 -left-1 w-2 h-2 bg-fg"></div>
            </motion.div>

            <h2 className="text-4xl md:text-6xl font-serif italic mb-6 group-hover:tracking-widest transition-all duration-500">
              Experience
            </h2>
            <div className="flex items-center gap-3 font-mono text-xs uppercase tracking-[0.3em] opacity-60">
              <MousePointerClick size={14} className="animate-pulse" />
              Click to Initialize Timeline
            </div>
          </motion.div>
        ) : (
          /* --- EXPANDED TIMELINE VIEW --- */
          <motion.div 
            key="timeline-view"
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            ref={containerRef}
            className="relative"
          >
