/**
 * CurvyPath Helper: Generates a zig-zag bezier path based on experience items
 */
const CurvyPath: React.FC<any> = ({ className, animate, style, strokeWidth = 1 }) => {
  const pathData = useMemo(() => {
    const itemCount = EXPERIENCE_DATA.length;
    // We treat the horizontal range from 200 to 800 (center 500)
    let d = "M 500 0"; // Start at top center

    for (let i = 0; i < itemCount; i++) {
      const isEven = i % 2 === 0;
      const targetX = isEven ? 300 : 700; // Zig-zag positions
      const startY = (i / itemCount) * 100;
      const endY = ((i + 1) / itemCount) * 100;
      const midY = (startY + endY) / 2;

      // Create a smooth curve to the node and back towards the center for the next stretch
      d += ` C 500 ${startY + 2}, ${targetX} ${startY + 5}, ${targetX} ${midY}`;
      d += ` C ${targetX} ${endY - 5}, 500 ${endY - 2}, 500 ${endY}`;
    }

    return d;
  }, []);

  return (
    <motion.path
      d={pathData}
      fill="transparent"
      strokeWidth={strokeWidth}
      strokeDasharray="1 0"
      className={className}
      animate={animate}
      style={style}
    />
  );
};

