/**
 * TimelinePath Helper: Generates a zig-zag bezier path that hits centers of nodes
 */
const TimelinePath: React.FC<any> = ({ className, animate, style, strokeWidth = 2 }) => {
  const pathData = useMemo(() => {
    const itemCount = EXPERIENCE_DATA.length;
    // Normalized viewBox coordinate space: 0 to 1000
    // We want the line to zig-zag horizontally (300 to 700)
    let d = "M 500 0"; // Start at absolute top center

    for (let i = 0; i < itemCount; i++) {
      const isEven = i % 2 === 0;
      const targetX = isEven ? 300 : 700; 
      const startY = (i / itemCount) * 1000;
      const endY = ((i + 1) / itemCount) * 1000;
      const midY = (startY + endY) / 2;

      // Hit the node (targetX, midY) then curve back to center for next segment
      d += ` C 500 ${startY + 20}, ${targetX} ${startY + 50}, ${targetX} ${midY}`;
      d += ` C ${targetX} ${endY - 50}, 500 ${endY - 20}, 500 ${endY}`;
    }

    // Extend to absolute bottom
    d += " L 500 1000";

    return d;
  }, []);

  return (
    <motion.path
      d={pathData}
      fill="transparent"
      strokeWidth={strokeWidth}
      strokeLinecap="round"
      className={className}
      animate={animate}
      style={style}
    />
  );
};

