      options: ["Missing dependency", "Direct mutation", "Infinite loop"],
      answer: 1,
      explanation: "Directly mutating state variables in React doesn't trigger a re-render. Always use the setter function."
    },
    {
      code: "useEffect(() => {\n  fetchData();\n}, [data]);",
      options: ["Race condition", "Missing return", "Missing dependency"],
      answer: 2,
      explanation: "If fetchData depends on 'data', it should be in the array, but if it updates 'data', you'll cause an infinite loop."
    },
    {
      code: "const items = ['a', 'b'];\nreturn (\n  <ul>\n    {items.map(i => <li>{i}</li>)}\n  </ul>\n);",
      options: ["Missing key", "Bad map", "Syntax error"],
      answer: 0,
      explanation: "Mapping elements in React requires a unique 'key' prop for optimal DOM reconciliation."
