           <pre>{BUGS[currentBug].code}</pre>
        </div>

        <div className="flex flex-col gap-4">
          {BUGS[currentBug].options.map((opt, i) => (
            <button
              key={i}
              onClick={() => handleSelect(i)}
              className={`p-6 border-2 font-mono text-left uppercase text-xs transition-all flex justify-between items-center ${
                selected === i 
                  ? (i === BUGS[currentBug].answer ? 'border-green-500 bg-green-500/10' : 'border-red-500 bg-red-500/10')
                  : 'border-fg hover:bg-fg hover:text-bg'
