};

// --- MINI DAW ---
const MiniDAW = () => {
  const STEPS = 16;
  const TRACKS = 8;
  const TRACK_TYPES = [
    { id: 'BD', name: 'Kick', variants: ['Deep', 'Punch', '808'] },
    { id: 'SD', name: 'Clap', variants: ['Tight', 'Clap', 'Rim'] },
    { id: 'CH', name: 'Hi-Hat', variants: ['Tss', 'Tick', 'Chh'] },
    { id: 'OH', name: 'Open Hat', variants: ['Open', 'Splash', 'Ride'] },
    { id: 'TM', name: 'Tom', variants: ['High', 'Low', 'Floor'] },
    { id: 'PR', name: 'Perc', variants: ['Wood', 'Click', 'Cowbell'] },
    { id: 'BS', name: 'Bass', variants: ['Sub', 'Saw', 'Pluck'] },
    { id: 'LD', name: 'Lead', variants: ['Square', 'Pulse', 'Arp'] },
  ];

  const [grid, setGrid] = useState<boolean[][]>(Array(TRACKS).fill(null).map(() => Array(STEPS).fill(false)));
  const [trackSamples, setTrackSamples] = useState<number[]>(Array(TRACKS).fill(0));
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentStep, setCurrentStep] = useState(-1);
  const [bpm, setBpm] = useState(128);
  const audioContextRef = useRef<AudioContext | null>(null);
  const timerRef = useRef<number | null>(null);

  useEffect(() => {
    const newGrid = [...grid];
    [0, 4, 8, 12].forEach(i => newGrid[0][i] = true);
    [4, 12].forEach(i => newGrid[1][i] = true);
    [2, 6, 10, 14].forEach(i => newGrid[2][i] = true);
    setGrid(newGrid);
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
      if (audioContextRef.current) audioContextRef.current.close();
    };
  }, []);

  const initAudio = () => {
    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    if (audioContextRef.current.state === 'suspended') audioContextRef.current.resume();
  };

  const playSound = (trackIndex: number, variantIndex: number) => {
    const ctx = audioContextRef.current;
    if (!ctx) return;
    const t = ctx.currentTime;
    const masterGain = ctx.createGain();
    masterGain.connect(ctx.destination);
    masterGain.gain.value = 0.4;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.connect(gain);
    gain.connect(masterGain);

    switch (trackIndex) {
      case 0: // Kick
        osc.frequency.setValueAtTime(variantIndex === 0 ? 150 : (variantIndex === 1 ? 180 : 80), t);
        osc.frequency.exponentialRampToValueAtTime(0.01, t + 0.5);
        gain.gain.setValueAtTime(1, t);
        gain.gain.exponentialRampToValueAtTime(0.01, t + 0.5);
        osc.start(t); osc.stop(t + 0.5); break;
      case 1: // Snare
        gain.gain.setValueAtTime(0.5, t);
        gain.gain.exponentialRampToValueAtTime(0.01, t + 0.2);
        osc.start(t); osc.stop(t + 0.2); break;
      default:
        osc.type = 'sine';
        osc.frequency.setValueAtTime(200 + (trackIndex * 100), t);
        gain.gain.setValueAtTime(0.2, t);
        gain.gain.exponentialRampToValueAtTime(0.01, t + 0.3);
        osc.start(t); osc.stop(t + 0.3); break;
    }
  };

  const togglePlay = () => {
    if (isPlaying) {
      setIsPlaying(false);
      setCurrentStep(-1);
      if (timerRef.current) clearInterval(timerRef.current);
    } else {
      initAudio();
      setIsPlaying(true);
      setCurrentStep(0);
      const interval = (60 / bpm) * 1000 / 4;
      timerRef.current = window.setInterval(() => {
        setCurrentStep(prev => {
          const next = (prev + 1) % STEPS;
          grid.forEach((trackSteps, idx) => {
            if (trackSteps[next]) playSound(idx, trackSamples[idx]);
          });
          return next;
        });
      }, interval);
    }
  };

  return (
    <div className="w-full h-full flex flex-col bg-bg text-fg">
      <div className="h-12 bg-fg text-bg flex items-center justify-between px-4">
        <button onClick={togglePlay} className={`px-4 py-1 border border-bg rounded text-xs font-bold ${isPlaying ? 'bg-bg text-fg' : ''}`}>
          {isPlaying ? <Square size={12} fill="currentColor" /> : <Play size={12} fill="currentColor" />}
        </button>
        <div className="text-xs">BPM: {bpm}</div>
      </div>
      <div className="flex-1 flex overflow-hidden">
        <div className="w-40 border-r border-fg">
          {TRACK_TYPES.map((t, i) => (
            <div key={i} className="h-12 border-b border-fg px-4 flex items-center font-mono text-[10px] uppercase font-bold">{t.name}</div>
          ))}
        </div>
        <div className="flex-1 overflow-x-auto">
          <div className="flex flex-col">
            {grid.map((track, trackIdx) => (
              <div key={trackIdx} className="h-12 border-b border-fg flex">
                {track.map((active, stepIdx) => (
                  <button
                    key={stepIdx}
                    onClick={() => {
                      const newGrid = [...grid];
                      newGrid[trackIdx][stepIdx] = !active;
                      setGrid(newGrid);
                    }}
                    className={`flex-1 border-r border-fg/20 ${active ? 'bg-fg' : 'hover:bg-fg/10'} ${currentStep === stepIdx ? 'bg-fg/30' : ''}`}
                  />
                ))}
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

