const TicTacToe = () => {
  const [board, setBoard] = useState<(string | null)[]>(Array(9).fill(null));
  const [xIsNext, setXIsNext] = useState(true);
  const [winner, setWinner] = useState<string | null>(null);

  const calculateWinner = (squares: (string | null)[]) => {
    const lines = [
      [0, 1, 2], [3, 4, 5], [6, 7, 8],
      [0, 3, 6], [1, 4, 7], [2, 5, 8],
      [0, 4, 8], [2, 4, 6],
    ];
    for (let i = 0; i < lines.length; i++) {
      const [a, b, c] = lines[i];
      if (squares[a] && squares[a] === squares[b] && squares[a] === squares[c]) {
        return squares[a];
      }
    }
    return null;
  };

  const handleClick = (i: number) => {
    if (winner || board[i]) return;
    const newBoard = board.slice();
    newBoard[i] = xIsNext ? 'X' : 'O';
    setBoard(newBoard);
    setXIsNext(!xIsNext);
    const win = calculateWinner(newBoard);
    if (win) setWinner(win);
    else if (!newBoard.includes(null)) setWinner('Draw');
  };

  const reset = () => {
    setBoard(Array(9).fill(null));
    setXIsNext(true);
    setWinner(null);
  };

  return (
    <div className="p-8 flex flex-col items-center justify-center h-full bg-bg">
      <div className="mb-8 text-center">
        <h3 className="font-serif text-3xl mb-2">Tic_Tac_Toe.exe</h3>
        <p className="font-mono text-xs opacity-50 uppercase tracking-widest">
          {winner ? (winner === 'Draw' ? "It's a tie!" : `Winner: ${winner}`) : `Next Turn: ${xIsNext ? 'X' : 'O'}`}
        </p>
      </div>

      <div className="grid grid-cols-3 gap-2 border-2 border-fg p-2 shadow-[10px_10px_0px_0px_var(--fg)]">
        {board.map((cell, i) => (
          <button
            key={i}
            onClick={() => handleClick(i)}
            className="w-20 h-20 md:w-24 md:h-24 border border-fg/20 flex items-center justify-center hover:bg-fg/5 transition-colors"
          >
            {cell === 'X' && <XIcon size={40} className="text-fg" />}
            {cell === 'O' && <Circle size={40} className="text-fg" />}
          </button>
        ))}
      </div>

      <button
        onClick={reset}
        className="mt-10 px-8 py-3 border-2 border-fg font-mono text-xs font-bold uppercase hover:bg-fg hover:text-bg transition-all"
      >
        Reboot Match
      </button>
    </div>
  );
};

// --- MINI DAW ---
const MiniDAW = () => {
  const STEPS = 16;
  const TRACKS = 8;
  const TRACK_TYPES = [
    { id: 'BD', name: 'Kick' },
    { id: 'SD', name: 'Clap' },
    { id: 'CH', name: 'Hi-Hat' },
    { id: 'OH', name: 'Open Hat' },
    { id: 'TM', name: 'Tom' },
    { id: 'PR', name: 'Perc' },
    { id: 'BS', name: 'Bass' },
    { id: 'LD', name: 'Lead' },
  ];

  const [grid, setGrid] = useState<boolean[][]>(Array(TRACKS).fill(null).map(() => Array(STEPS).fill(false)));
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentStep, setCurrentStep] = useState(-1);
  const [bpm, setBpm] = useState(128);
  const audioContextRef = useRef<AudioContext | null>(null);
  const timerRef = useRef<number | null>(null);

  useEffect(() => {
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
      if (audioContextRef.current) audioContextRef.current.close();
    };
  }, []);

  const initAudio = () => {
    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    if (audioContextRef.current.state === 'suspended') audioContextRef.current.resume();
  };

  const playSound = (trackIndex: number) => {
    const ctx = audioContextRef.current;
    if (!ctx) return;
    const t = ctx.currentTime;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.connect(gain);
    gain.connect(ctx.destination);

    switch (trackIndex) {
      case 0: osc.frequency.setValueAtTime(150, t); osc.frequency.exponentialRampToValueAtTime(0.01, t + 0.5); break;
      case 1: osc.type = 'square'; gain.gain.setValueAtTime(0.1, t); break;
      default: osc.frequency.setValueAtTime(200 + (trackIndex * 100), t); break;
    }
    gain.gain.exponentialRampToValueAtTime(0.01, t + 0.3);
    osc.start(t); osc.stop(t + 0.3);
  };

  const togglePlay = () => {
    if (isPlaying) {
      setIsPlaying(false);
      setCurrentStep(-1);
      if (timerRef.current) clearInterval(timerRef.current);
    } else {
      initAudio();
      setIsPlaying(true);
      setCurrentStep(0);
      const interval = (60 / bpm) * 1000 / 4;
      timerRef.current = window.setInterval(() => {
        setCurrentStep(prev => {
          const next = (prev + 1) % STEPS;
          grid.forEach((trackSteps, idx) => {
            if (trackSteps[next]) playSound(idx);
          });
          return next;
        });
      }, interval);
    }
  };

  return (
    <div className="w-full h-full flex flex-col bg-bg text-fg overflow-hidden">
      <div className="h-12 bg-fg text-bg flex items-center justify-between px-4 shrink-0">
        <button onClick={togglePlay} className={`px-4 py-1 border border-bg rounded text-xs font-bold ${isPlaying ? 'bg-bg text-fg' : ''}`}>
          {isPlaying ? <Square size={12} fill="currentColor" /> : <Play size={12} fill="currentColor" />}
        </button>
        <div className="text-xs font-mono">BPM: {bpm}</div>
      </div>
      <div className="flex-1 flex overflow-hidden">
        <div className="w-32 border-r border-fg shrink-0 bg-fg/5">
          {TRACK_TYPES.map((t, i) => (
            <div key={i} className="h-12 border-b border-fg/10 px-4 flex items-center font-mono text-[9px] uppercase font-bold">{t.name}</div>
          ))}
        </div>
        <div className="flex-1 overflow-x-auto custom-scrollbar">
          <div className="flex flex-col min-w-max">
            {grid.map((track, trackIdx) => (
              <div key={trackIdx} className="h-12 border-b border-fg/10 flex">
                {track.map((active, stepIdx) => (
                  <button
                    key={stepIdx}
                    onClick={() => {
                      const newGrid = [...grid];
                      newGrid[trackIdx][stepIdx] = !active;
                      setGrid(newGrid);
                    }}
                    className={`w-12 border-r border-fg/10 transition-colors ${active ? 'bg-fg' : 'hover:bg-fg/5'} ${currentStep === stepIdx ? 'ring-inset ring-2 ring-fg/40' : ''}`}
                  />
                ))}
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

