const VisitorStats = () => {
  const [stats, setStats] = useState({ visitors: 1482, avgStay: "2m 14s" });

  useEffect(() => {
    // Persistent visitor counter logic
    const baseCount = 1482;
    const storedCount = localStorage.getItem('v_count');
    let currentCount = storedCount ? parseInt(storedCount) : baseCount;

    // Only increment once per session to maintain realism
    if (!sessionStorage.getItem('v_session')) {
      currentCount += 1;
      localStorage.setItem('v_count', currentCount.toString());
      sessionStorage.setItem('v_session', 'active');
    }

    setStats(prev => ({ ...prev, visitors: currentCount }));

    // Slow "live" increments to simulate ongoing traffic
    const interval = setInterval(() => {
      setStats(prev => {
        const shouldIncrement = Math.random() > 0.85;
        const next = shouldIncrement ? prev.visitors + 1 : prev.visitors;
        if (shouldIncrement) localStorage.setItem('v_count', next.toString());
        return { ...prev, visitors: next };
      });
    }, 20000);

    return () => clearInterval(interval);
  }, []);

  return (
    <div className="flex flex-wrap justify-center gap-12 md:gap-24 border-t border-fg/10 pt-12 mt-12 w-full">
      <div className="flex flex-col items-center gap-2">
        <UserCheck size={20} className="opacity-40" />
