import React, { useRef, useEffect } from 'react';
import { SKILLS_DATA } from '../constants';
import { SkillCategory } from '../types';

const BinaryRainCanvas: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const resizeCanvas = () => {
      if (canvas.parentElement) {
        canvas.width = canvas.parentElement.offsetWidth;
        canvas.height = canvas.parentElement.offsetHeight;
      }
    };
    resizeCanvas();
    window.addEventListener('resize', resizeCanvas);

    const fontSize = 14;
    const columns = Math.ceil(canvas.width / fontSize);
    const drops = Array(columns).fill(0).map(() => Math.random() * -100);
    const chars = "01";

    const getColors = () => {
      const style = getComputedStyle(document.body);
      return {
        fg: style.getPropertyValue('--fg').trim(),
        bg: style.getPropertyValue('--bg').trim()
      };
    };

    let animationId: number;

    const draw = () => {
      const colors = getColors();
      ctx.fillStyle = colors.bg;
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      ctx.fillStyle = colors.fg;
      ctx.globalAlpha = 0.05; // Faint as per reference
      ctx.font = `${fontSize}px monospace`;

      for (let i = 0; i < drops.length; i++) {
        const text = chars[Math.floor(Math.random() * chars.length)];
        ctx.fillText(text, i * fontSize, drops[i] * fontSize);

        if (drops[i] * fontSize > canvas.height && Math.random() > 0.975) {
          drops[i] = 0;
        }
        drops[i] += 0.5;
      }
      animationId = requestAnimationFrame(draw);
    };

    draw();

    return () => {
      window.removeEventListener('resize', resizeCanvas);
      cancelAnimationFrame(animationId);
    };
  }, []);

  return (
    <canvas 
      ref={canvasRef} 
      className="absolute inset-0 pointer-events-none z-0" 
    />
  );
};

const SkillCard: React.FC<{ category: SkillCategory, index: number }> = ({ category, index }) => {
  const showBinary = category.category === "LANGUAGES";

  return (
    <div 
      className={`relative border-b border-fg p-12 overflow-hidden flex flex-col ${index % 2 === 0 ? 'sm:border-r' : ''}`}
    >
      {showBinary && <BinaryRainCanvas />}

      <div className="relative z-10">
        <h3 className="font-mono text-[10px] uppercase font-bold mb-8 border-b border-fg inline-block pb-1 tracking-[0.2em]">
            {category.category}
        </h3>
        <ul className="space-y-4">
            {category.items.map(item => (
                <li key={item} className="font-serif text-2xl md:text-3xl leading-none hover:italic transition-all cursor-default w-fit">
                    {item}
                </li>
            ))}
        </ul>
      </div>
    </div>
  );
};

