/**
 * Optimized BinaryRainCanvas that handles hover states without resetting the animation loop.
 */
const BinaryRainCanvas: React.FC<{ isHovered: boolean }> = ({ isHovered }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const hoveredRef = useRef(isHovered);

  // Sync the ref with the prop to avoid re-triggering the main effect and flickering
  useEffect(() => {
    hoveredRef.current = isHovered;
  }, [isHovered]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const resizeCanvas = () => {
      if (canvas.parentElement) {
        canvas.width = canvas.parentElement.offsetWidth;
        canvas.height = canvas.parentElement.offsetHeight;
      }
    };
    resizeCanvas();
    window.addEventListener('resize', resizeCanvas);

    const fontSize = 14;
    const columns = Math.ceil(canvas.width / fontSize);
    const drops = Array(columns).fill(0).map(() => Math.random() * -100);
    const chars = "01";

    const getColors = () => {
      const style = getComputedStyle(document.body);
      return {
        fg: style.getPropertyValue('--fg').trim(),
        bg: style.getPropertyValue('--bg').trim()
      };
    };

    let animationId: number;

    const draw = () => {
      const colors = getColors();
      const currentHovered = hoveredRef.current;

      // Draw background with slight trail effect
      ctx.fillStyle = colors.bg;
      ctx.globalAlpha = 0.2; // Adjust for trail length
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      ctx.fillStyle = colors.fg;
      // Use different opacity based on hover state
      ctx.globalAlpha = currentHovered ? 0.2 : 0.03;
      ctx.font = `${fontSize}px monospace`;

      for (let i = 0; i < drops.length; i++) {
        const text = chars[Math.floor(Math.random() * chars.length)];
        ctx.fillText(text, i * fontSize, drops[i] * fontSize);

        if (drops[i] * fontSize > canvas.height && Math.random() > 0.975) {
          drops[i] = 0;
        }

        // Speed logic: faster when hovered
        const speed = currentHovered ? 1.5 : 0.4;
        drops[i] += speed;
      }
      animationId = requestAnimationFrame(draw);
    };

    draw();

    return () => {
      window.removeEventListener('resize', resizeCanvas);
      cancelAnimationFrame(animationId);
    };
  }, []); // Run once on mount

  return (
    <canvas 
      ref={canvasRef} 
      className="absolute inset-0 pointer-events-none z-0 transition-opacity duration-700" 
      style={{ opacity: 1 }}
    />
  );
};

const RatingIndicator: React.FC<{ score: number }> = ({ score }) => {
  const segments = 20; // More segments for a finer futuristic look
  const activeSegments = Math.round((score / 100) * segments);

  return (
    <div className="flex flex-col gap-3">
      <div className="flex justify-between items-end">
        <div className="flex items-center gap-2">
          <Cpu size={12} className="opacity-40" />
          <span className="font-mono text-[9px] uppercase opacity-50 tracking-[0.2em]">Efficiency_Rating</span>
        </div>
        <span className="font-mono text-xl font-bold tracking-tighter">{score}%</span>
      </div>
      <div className="flex gap-1 h-2">
        {Array.from({ length: segments }).map((_, i) => (
          <motion.div 
            key={i}
            initial={{ scaleY: 0.5, opacity: 0.2 }}
            animate={{ 
              scaleY: i < activeSegments ? 1 : 0.5,
              opacity: i < activeSegments ? 1 : 0.1,
            }}
            className={`flex-1 border-r border-fg/10 ${i < activeSegments ? 'bg-fg shadow-[0px_0px_10px_var(--fg)]' : 'bg-transparent'}`}
          />
        ))}
      </div>
    </div>
  );
};

