/**
 * Optimized BinaryRainCanvas that handles hover states smoothly.
 * Enhanced to ensure the canvas always matches the full dimensions of the parent SkillCard.
 */
const BinaryRainCanvas: React.FC<{ isHovered: boolean }> = ({ isHovered }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const hoveredRef = useRef(isHovered);

  useEffect(() => {
    hoveredRef.current = isHovered;
  }, [isHovered]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const resizeCanvas = () => {
      const parent = canvas.parentElement;
      if (parent) {
        const dpr = window.devicePixelRatio || 1;
        canvas.width = parent.offsetWidth * dpr;
        canvas.height = parent.offsetHeight * dpr;
        ctx.scale(dpr, dpr);
        canvas.style.width = `${parent.offsetWidth}px`;
        canvas.style.height = `${parent.offsetHeight}px`;
      }
    };

    resizeCanvas();
    window.addEventListener('resize', resizeCanvas);

    const fontSize = 12;
    const columns = Math.ceil(1920 / fontSize); // Sufficient columns for most screens
    let drops = Array(columns).fill(0).map(() => Math.random() * -100);
    const chars = "01";

    const getColors = () => {
      const style = getComputedStyle(document.body);
      return {
        fg: style.getPropertyValue('--fg').trim(),
        bg: style.getPropertyValue('--bg').trim()
      };
    };

    let animationId: number;

    const draw = () => {
      const colors = getColors();
      const currentHovered = hoveredRef.current;
      const canvasW = canvas.width / (window.devicePixelRatio || 1);
      const canvasH = canvas.height / (window.devicePixelRatio || 1);

      ctx.fillStyle = colors.bg;
      ctx.globalAlpha = 0.2;
      ctx.fillRect(0, 0, canvasW, canvasH);

      ctx.fillStyle = colors.fg;
      ctx.globalAlpha = currentHovered ? 0.2 : 0.02;
      ctx.font = `${fontSize}px monospace`;

      for (let i = 0; i < drops.length; i++) {
        const text = chars[Math.floor(Math.random() * chars.length)];
        ctx.fillText(text, i * fontSize, drops[i] * fontSize);

        if (drops[i] * fontSize > canvasH && Math.random() > 0.975) {
          drops[i] = 0;
        }
        drops[i] += currentHovered ? 1.5 : 0.4;
      }
      animationId = requestAnimationFrame(draw);
    };

    draw();

    return () => {
      window.removeEventListener('resize', resizeCanvas);
      cancelAnimationFrame(animationId);
    };
  }, []);

  return (
    <canvas 
      ref={canvasRef} 
      className="absolute inset-0 pointer-events-none z-0" 
      style={{ display: 'block' }}
    />
  );
};

const RatingIndicator: React.FC<{ score: number }> = ({ score }) => {
  const segments = 20;
  const activeSegments = Math.round((score / 100) * segments);

  return (
    <div className="flex flex-col gap-3">
      <div className="flex justify-between items-end">
        <div className="flex items-center gap-2">
          <Cpu size={12} className="opacity-40" />
          <span className="font-mono text-[9px] uppercase opacity-50 tracking-[0.2em]">Efficiency_Rating</span>
        </div>
        <span className="font-mono text-lg font-bold tracking-tighter">{score}%</span>
      </div>
      <div className="flex gap-1 h-1.5">
        {Array.from({ length: segments }).map((_, i) => (
          <motion.div 
            key={i}
            initial={{ scaleY: 0.5, opacity: 0.2 }}
            animate={{ 
              scaleY: i < activeSegments ? 1 : 0.5,
              opacity: i < activeSegments ? 1 : 0.1,
            }}
            className={`flex-1 border-r border-fg/10 ${i < activeSegments ? 'bg-fg shadow-[0px_0px_10px_var(--fg)]' : 'bg-transparent'}`}
          />
        ))}
      </div>
    </div>
  );
};

