    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const fontSize = 12;

    const resizeCanvas = () => {
      const parent = canvas.parentElement;
      if (parent) {
        const dpr = window.devicePixelRatio || 1;
        canvas.width = parent.offsetWidth * dpr;
        canvas.height = parent.offsetHeight * dpr;
        ctx.scale(dpr, dpr);
        canvas.style.width = `${parent.offsetWidth}px`;
        canvas.style.height = `${parent.offsetHeight}px`;

        // Initialize or update drops based on new width
        const columns = Math.ceil(parent.offsetWidth / fontSize);
        if (dropsRef.current.length < columns) {
          const newDrops = Array(columns - dropsRef.current.length).fill(0).map(() => Math.random() * -100);
          dropsRef.current = [...dropsRef.current, ...newDrops];
        }
      }
    };

    resizeCanvas();
    window.addEventListener('resize', resizeCanvas);

    const chars = "01";

    const getColors = () => {
      const style = getComputedStyle(document.body);
      return {
        fg: style.getPropertyValue('--fg').trim(),
        bg: style.getPropertyValue('--bg').trim()
      };
    };

    let animationId: number;

    const draw = () => {
      const colors = getColors();
      const currentHovered = hoveredRef.current;
      const canvasW = canvas.width / (window.devicePixelRatio || 1);
      const canvasH = canvas.height / (window.devicePixelRatio || 1);

      ctx.fillStyle = colors.bg;
      ctx.globalAlpha = 0.2;
      ctx.fillRect(0, 0, canvasW, canvasH);

      ctx.fillStyle = colors.fg;
      ctx.globalAlpha = currentHovered ? 0.25 : 0.02;
      ctx.font = `${fontSize}px monospace`;

      for (let i = 0; i < dropsRef.current.length; i++) {
        const text = chars[Math.floor(Math.random() * chars.length)];
        ctx.fillText(text, i * fontSize, dropsRef.current[i] * fontSize);

        if (dropsRef.current[i] * fontSize > canvasH && Math.random() > 0.975) {
          dropsRef.current[i] = 0;
        }
        dropsRef.current[i] += currentHovered ? 1.8 : 0.4;
      }
      animationId = requestAnimationFrame(draw);
    };

    draw();

    return () => {
      window.removeEventListener('resize', resizeCanvas);
      cancelAnimationFrame(animationId);
    };
  }, []);

  return (
    <canvas 
      ref={canvasRef} 
      className="absolute inset-0 pointer-events-none z-0" 
      style={{ display: 'block' }}
    />
  );
};

