  const [isTraining, setIsTraining] = useState(false);
  const [lossHistory, setLossHistory] = useState<number[]>([]);
  const [status, setStatus] = useState<'IDLE' | 'TRAINING' | 'EXPLODED' | 'CONVERGED'>('IDLE');

  const runSimulation = async () => {
    setIsTraining(true);
    setStatus('TRAINING');
    setLossHistory([]);

    let currentLoss = 100;
    let weight = 10;
    const history: number[] = [currentLoss];

    for (let i = 0; i < epochs; i++) {
      if (!isTraining && i > 0) break; // Allow stopping if we had a stop button

      // f(w) = w^2 + reg * w^2
      // grad = 2w + 2 * reg * w
      const gradient = 2 * weight * (1 + reg);
      weight = weight - lr * gradient;
      currentLoss = Math.pow(weight, 2);

      history.push(currentLoss);
      setLossHistory([...history]);

      if (currentLoss > 100000 || isNaN(currentLoss)) {
        setStatus('EXPLODED');
        setIsTraining(false);
        return;
      }

      await new Promise(resolve => setTimeout(resolve, 50));
    }

    setStatus(currentLoss < 0.1 ? 'CONVERGED' : 'IDLE');
    setIsTraining(false);
  };

  const chartData = useMemo(() => {
    if (lossHistory.length === 0) return "";
    const maxLoss = Math.max(...lossHistory.filter(l => !isNaN(l) && isFinite(l)), 100);
    const width = 800;
    const height = 300;

    return lossHistory.map((loss, i) => {
      const x = (i / epochs) * width;
      const y = height - (Math.min(loss, maxLoss) / maxLoss) * height;
      return `${x},${y}`;
    }).join(" ");
  }, [lossHistory, epochs]);

  return (
    <div className="p-8 md:p-12 flex flex-col gap-8 bg-bg h-full">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h3 className="font-serif text-3xl italic mb-1">Model_Trainer_v1.0</h3>
          <p className="font-mono text-[10px] uppercase opacity-40 tracking-widest">Neural Architecture Simulator</p>
        </div>
        <div className={`px-4 py-2 border font-mono text-xs font-bold uppercase tracking-tighter ${
          status === 'EXPLODED' ? 'bg-red-500 text-white border-red-500' : 
          status === 'CONVERGED' ? 'bg-green-500 text-white border-green-500' :
          'bg-fg text-bg border-fg'
        }`}>
          KERNEL_STATUS: {status}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {/* Controls */}
        <div className="space-y-6 bg-fg/5 p-6 border border-fg/10">
          <div className="space-y-3">
            <div className="flex justify-between font-mono text-[10px] uppercase opacity-60">
              <span>Learning Rate</span>
              <span>{lr.toFixed(3)}</span>
            </div>
            <input 
              type="range" min="0.001" max="1.5" step="0.001" 
              value={lr} onChange={(e) => setLr(parseFloat(e.target.value))}
              disabled={isTraining}
              className="w-full accent-fg h-1 bg-fg/10 appearance-none cursor-pointer"
            />
            <p className="text-[9px] font-mono opacity-40 italic">Controls gradient step size. Too high = Instability.</p>
          </div>

          <div className="space-y-3">
            <div className="flex justify-between font-mono text-[10px] uppercase opacity-60">
              <span>Epochs</span>
              <span>{epochs}</span>
            </div>
            <input 
              type="range" min="10" max="200" step="1" 
              value={epochs} onChange={(e) => setEpochs(parseInt(e.target.value))}
              disabled={isTraining}
              className="w-full accent-fg h-1 bg-fg/10 appearance-none cursor-pointer"
            />
          </div>

          <div className="space-y-3">
            <div className="flex justify-between font-mono text-[10px] uppercase opacity-60">
              <span>Regularization</span>
              <span>{reg.toFixed(2)}</span>
            </div>
            <input 
              type="range" min="0" max="2" step="0.01" 
              value={reg} onChange={(e) => setReg(parseFloat(e.target.value))}
              disabled={isTraining}
              className="w-full accent-fg h-1 bg-fg/10 appearance-none cursor-pointer"
            />
          </div>

          <button 
            onClick={runSimulation}
            disabled={isTraining}
            className="w-full py-4 border-2 border-fg font-mono text-xs font-bold uppercase hover:bg-fg hover:text-bg transition-all flex items-center justify-center gap-3"
          >
            {isTraining ? <RefreshCw size={14} className="animate-spin" /> : <Zap size={14} />}
            {isTraining ? "Synthesizing..." : "Initialize Training"}
          </button>
        </div>

        {/* Graph */}
        <div className="md:col-span-2 border border-fg relative bg-bg overflow-hidden flex flex-col">
          <div className="p-3 border-b border-fg bg-fg/5 flex justify-between font-mono text-[9px] uppercase opacity-50">
            <span>Loss Curve</span>
            <span>Scale: Logarithmic</span>
          </div>
          <div className="flex-1 p-4 relative min-h-[300px]">
            <svg width="100%" height="100%" viewBox="0 0 800 300" preserveAspectRatio="none" className="overflow-visible">
              {/* Grid Lines */}
              <line x1="0" y1="0" x2="800" y2="0" stroke="currentColor" strokeOpacity="0.1" />
              <line x1="0" y1="75" x2="800" y2="75" stroke="currentColor" strokeOpacity="0.1" />
              <line x1="0" y1="150" x2="800" y2="150" stroke="currentColor" strokeOpacity="0.1" />
              <line x1="0" y1="225" x2="800" y2="225" stroke="currentColor" strokeOpacity="0.1" />

              <polyline
                fill="none"
                stroke="currentColor"
                strokeWidth="2"
                points={chartData}
                className="transition-all duration-300"
              />
            </svg>

            {status === 'EXPLODED' && (
              <motion.div 
                initial={{ opacity: 0 }} animate={{ opacity: 1 }}
                className="absolute inset-0 flex items-center justify-center bg-red-500/10 backdrop-blur-[1px]"
              >
                <div className="text-red-500 font-mono text-xl font-bold border-2 border-red-500 px-6 py-3 bg-bg">
                  GRADIENT_EXPLOSION_DETECTED
                </div>
              </motion.div>
            )}

            {lossHistory.length === 0 && (
              <div className="absolute inset-0 flex items-center justify-center font-mono text-[10px] uppercase opacity-20">
                Waiting for initialization...
              </div>
            )}
          </div>
          <div className="p-3 border-t border-fg bg-fg/5 flex justify-between font-mono text-[9px] uppercase opacity-40">
            <span>W: {lossHistory[lossHistory.length - 1]?.toFixed(4) || '0.0000'}</span>
            <span>Step: {lossHistory.length}/{epochs}</span>
          </div>
        </div>
      </div>
    </div>
  );
};

// --- TIC TAC TOE ---
const TicTacToe = () => {
  const [board, setBoard] = useState<(string | null)[]>(Array(9).fill(null));
  const [xIsNext, setXIsNext] = useState(true);
  const [winner, setWinner] = useState<string | null>(null);

  const calculateWinner = (squares: (string | null)[]) => {
    const lines = [
      [0, 1, 2], [3, 4, 5], [6, 7, 8],
      [0, 3, 6], [1, 4, 7], [2, 5, 8],
      [0, 4, 8], [2, 4, 6],
    ];
    for (let i = 0; i < lines.length; i++) {
      const [a, b, c] = lines[i];
      if (squares[a] && squares[a] === squares[b] && squares[a] === squares[c]) {
        return squares[a];
      }
    }
    return null;
  };

  const handleClick = (i: number) => {
    if (winner || board[i]) return;
    const newBoard = board.slice();
    newBoard[i] = xIsNext ? 'X' : 'O';
    setBoard(newBoard);
    setXIsNext(!xIsNext);
    const win = calculateWinner(newBoard);
    if (win) setWinner(win);
    else if (!newBoard.includes(null)) setWinner('Draw');
  };

  const reset = () => {
    setBoard(Array(9).fill(null));
    setXIsNext(true);
    setWinner(null);
  };

  return (
    <div className="p-8 flex flex-col items-center justify-center h-full bg-bg">
      <div className="mb-8 text-center">
        <h3 className="font-serif text-3xl mb-2 italic">Tic_Tac_Toe.exe</h3>
        <p className="font-mono text-xs opacity-50 uppercase tracking-[0.2em]">
          {winner ? (winner === 'Draw' ? "STATUS: STALEMATE" : `WINNER: ${winner}`) : `ACTIVE TURN: ${xIsNext ? 'X' : 'O'}`}
        </p>
      </div>

      <div className="grid grid-cols-3 gap-2 border-2 border-fg p-2 shadow-[10px_10px_0px_0px_var(--fg)] bg-fg/5">
        {board.map((cell, i) => (
          <button
            key={i}
            onClick={() => handleClick(i)}
            className="w-20 h-20 md:w-24 md:h-24 border border-fg/20 flex items-center justify-center hover:bg-fg/10 transition-colors bg-bg"
          >
            {cell === 'X' && <XIcon size={40} className="text-fg" />}
            {cell === 'O' && <Circle size={40} className="text-fg" />}
          </button>
        ))}
      </div>

      <button
        onClick={reset}
        className="mt-10 px-12 py-3 border-2 border-fg font-mono text-[10px] font-bold uppercase hover:bg-fg hover:text-bg transition-all tracking-widest"
      >
        Reboot Match
      </button>
    </div>
  );
};

// --- MINI DAW ---
const MiniDAW = () => {
  const STEPS = 16;
  const TRACKS = 8;
  const TRACK_TYPES = [
    { id: 'BD', name: 'Kick' },
    { id: 'SD', name: 'Clap' },
    { id: 'CH', name: 'Hi-Hat' },
    { id: 'OH', name: 'Open Hat' },
    { id: 'TM', name: 'Tom' },
    { id: 'PR', name: 'Perc' },
    { id: 'BS', name: 'Bass' },
    { id: 'LD', name: 'Lead' },
  ];

  const [grid, setGrid] = useState<boolean[][]>(Array(TRACKS).fill(null).map(() => Array(STEPS).fill(false)));
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentStep, setCurrentStep] = useState(-1);
  const [bpm, setBpm] = useState(128);
  const audioContextRef = useRef<AudioContext | null>(null);
  const timerRef = useRef<number | null>(null);

  useEffect(() => {
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
      if (audioContextRef.current) audioContextRef.current.close();
    };
  }, []);

  const initAudio = () => {
    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    if (audioContextRef.current.state === 'suspended') audioContextRef.current.resume();
  };

  const playSound = (trackIndex: number) => {
    const ctx = audioContextRef.current;
    if (!ctx) return;
    const t = ctx.currentTime;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.connect(gain);
    gain.connect(ctx.destination);

    switch (trackIndex) {
      case 0: osc.frequency.setValueAtTime(150, t); osc.frequency.exponentialRampToValueAtTime(0.01, t + 0.5); break;
      case 1: osc.type = 'square'; gain.gain.setValueAtTime(0.1, t); break;
      default: osc.frequency.setValueAtTime(200 + (trackIndex * 100), t); break;
    }
    gain.gain.exponentialRampToValueAtTime(0.01, t + 0.3);
    osc.start(t); osc.stop(t + 0.3);
  };

  const togglePlay = () => {
    if (isPlaying) {
      setIsPlaying(false);
      setCurrentStep(-1);
      if (timerRef.current) clearInterval(timerRef.current);
    } else {
      initAudio();
      setIsPlaying(true);
      setCurrentStep(0);
      const interval = (60 / bpm) * 1000 / 4;
      timerRef.current = window.setInterval(() => {
        setCurrentStep(prev => {
          const next = (prev + 1) % STEPS;
          grid.forEach((trackSteps, idx) => {
            if (trackSteps[next]) playSound(idx);
          });
          return next;
        });
      }, interval);
    }
  };

  return (
    <div className="w-full h-full flex flex-col bg-bg text-fg overflow-hidden">
      <div className="h-12 bg-fg text-bg flex items-center justify-between px-4 shrink-0">
        <button onClick={togglePlay} className={`px-4 py-1 border border-bg rounded text-xs font-bold transition-all ${isPlaying ? 'bg-bg text-fg scale-95' : 'hover:scale-105'}`}>
          {isPlaying ? <Square size={12} fill="currentColor" /> : <Play size={12} fill="currentColor" />}
        </button>
        <div className="text-[10px] font-mono uppercase font-bold tracking-widest">Clock Speed: {bpm} BPM</div>
      </div>
      <div className="flex-1 flex overflow-hidden">
        <div className="w-32 border-r border-fg shrink-0 bg-fg/5">
          {TRACK_TYPES.map((t, i) => (
            <div key={i} className="h-12 border-b border-fg/10 px-4 flex items-center font-mono text-[9px] uppercase font-bold opacity-60">{t.name}</div>
          ))}
        </div>
        <div className="flex-1 overflow-x-auto custom-scrollbar">
          <div className="flex flex-col min-w-max">
            {grid.map((track, trackIdx) => (
              <div key={trackIdx} className="h-12 border-b border-fg/10 flex">
                {track.map((active, stepIdx) => (
                  <button
                    key={stepIdx}
                    onClick={() => {
                      const newGrid = [...grid];
                      newGrid[trackIdx][stepIdx] = !active;
                      setGrid(newGrid);
                    }}
                    className={`w-12 border-r border-fg/10 transition-all ${active ? 'bg-fg scale-90 rounded-sm' : 'hover:bg-fg/5'} ${currentStep === stepIdx ? 'ring-inset ring-2 ring-fg/20' : ''}`}
                  />
                ))}
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

