// --- WAVEFORM ARCHITECT (OSCILLOSCOPE) ---
const WaveformArchitect = () => {
  const [freq, setFreq] = useState(440);
  const [amp, setAmp] = useState(0.5);
  const [type, setType] = useState<OscillatorType>('sine');
  const [isAudioOn, setIsAudioOn] = useState(false);
  const audioCtxRef = useRef<AudioContext | null>(null);
  const oscRef = useRef<OscillatorNode | null>(null);
  const gainRef = useRef<GainNode | null>(null);

  useEffect(() => {
    return () => {
      stopAudio();
    };
  }, []);

  const initAudio = () => {
    if (!audioCtxRef.current) {
      audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    if (audioCtxRef.current.state === 'suspended') {
      audioCtxRef.current.resume();
    }
  };

  const startAudio = () => {
    initAudio();
    if (!audioCtxRef.current) return;

    stopAudio(); // Clean previous

    const osc = audioCtxRef.current.createOscillator();
    const gain = audioCtxRef.current.createGain();

    osc.type = type;
    osc.frequency.setValueAtTime(freq, audioCtxRef.current.currentTime);
    gain.gain.setValueAtTime(amp * 0.2, audioCtxRef.current.currentTime); // Low volume safety

    osc.connect(gain);
    gain.connect(audioCtxRef.current.destination);

    osc.start();
    oscRef.current = osc;
    gainRef.current = gain;
    setIsAudioOn(true);
  };

  const stopAudio = () => {
    if (oscRef.current) {
      try { oscRef.current.stop(); } catch(e) {}
      oscRef.current.disconnect();
    }
    if (gainRef.current) {
      gainRef.current.disconnect();
    }
    setIsAudioOn(false);
  };

  useEffect(() => {
    if (isAudioOn && oscRef.current && audioCtxRef.current) {
      oscRef.current.frequency.setTargetAtTime(freq, audioCtxRef.current.currentTime, 0.05);
      oscRef.current.type = type;
    }
  }, [freq, type]);

  useEffect(() => {
    if (isAudioOn && gainRef.current && audioCtxRef.current) {
      gainRef.current.gain.setTargetAtTime(amp * 0.2, audioCtxRef.current.currentTime, 0.05);
    }
  }, [amp]);

  // Generate the SVG path points for the wave visualization
  const points = useMemo(() => {
    const width = 800;
    const height = 300;
    const centerY = height / 2;
    const samples = 200;
    const result: string[] = [];

    for (let i = 0; i <= samples; i++) {
      const x = (i / samples) * width;
      const t = (i / samples) * Math.PI * 4; // 2 cycles

      let yVal = 0;
      const phase = (freq / 100) * t;

      if (type === 'sine') {
        yVal = Math.sin(phase);
      } else if (type === 'square') {
        yVal = Math.sin(phase) >= 0 ? 1 : -1;
      } else if (type === 'sawtooth') {
        yVal = 2 * (phase / (2 * Math.PI) - Math.floor(0.5 + phase / (2 * Math.PI)));
      } else if (type === 'triangle') {
        yVal = (2 / Math.PI) * Math.asin(Math.sin(phase));
      }

      const y = centerY - (yVal * amp * (height / 2.5));
      result.push(`${x},${y}`);
    }
    return result.join(" ");
  }, [freq, amp, type]);

  return (
    <div className="p-8 md:p-12 flex flex-col gap-8 bg-bg h-full">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h3 className="font-serif text-3xl italic mb-1">Waveform_Architect</h3>
          <p className="font-mono text-[10px] uppercase opacity-40 tracking-widest">Signal Synthesis Unit // Spectral_Engine</p>
        </div>
        <div className="flex gap-2">
           <div className="px-4 py-2 border border-fg font-mono text-[10px] uppercase font-bold tracking-tighter bg-fg/5">
            SIGNAL: {isAudioOn ? 'ACTIVE' : 'STANDBY'}
          </div>
          <div className="px-4 py-2 border border-fg font-mono text-[10px] uppercase font-bold tracking-tighter bg-fg text-bg">
            FREQ: {freq} Hz
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
        {/* Controls Column */}
        <div className="space-y-8 bg-fg/5 p-8 border border-fg/10">
          <div className="space-y-4">
             <label className="flex justify-between font-mono text-[10px] uppercase opacity-60">
                <span>Frequency</span>
                <span>{freq} Hz</span>
             </label>
             <input 
                type="range" min="20" max="2000" step="1" 
                value={freq} onChange={(e) => setFreq(parseInt(e.target.value))}
                className="w-full accent-fg h-1 bg-fg/10 appearance-none cursor-pointer"
             />
          </div>

          <div className="space-y-4">
             <label className="flex justify-between font-mono text-[10px] uppercase opacity-60">
