  const canvasRef = useRef<HTMLCanvasElement>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const sourceRef = useRef<MediaStreamAudioSourceNode | OscillatorNode | null>(null);
  const gainRef = useRef<GainNode | null>(null);
  const animationIdRef = useRef<number | null>(null);

  const initAudio = () => {
    if (!audioCtxRef.current) {
      audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    if (!analyserRef.current) {
      analyserRef.current = audioCtxRef.current.createAnalyser();
      analyserRef.current.fftSize = 2048;
    }
    if (audioCtxRef.current.state === 'suspended') {
      audioCtxRef.current.resume();
    }
  };

  const stopAll = () => {
    setError(null);
    if (sourceRef.current) {
      try { (sourceRef.current as any).stop(); } catch(e) {}
      sourceRef.current.disconnect();
    }
    if (gainRef.current) gainRef.current.disconnect();
    if (animationIdRef.current) cancelAnimationFrame(animationIdRef.current);
    setIsProcessing(false);
  };

  const startSynth = () => {
    initAudio();
    stopAll();
    const ctx = audioCtxRef.current!;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();

    osc.type = type;
    osc.frequency.setValueAtTime(freq, ctx.currentTime);
    gain.gain.setValueAtTime(amp * 0.1, ctx.currentTime);

    osc.connect(gain);
    gain.connect(analyserRef.current!);
    gain.connect(ctx.destination);

    osc.start();
    sourceRef.current = osc;
    gainRef.current = gain;
    draw();
    setIsProcessing(true);
  };

  const startMic = async () => {
    initAudio();
    stopAll();
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const ctx = audioCtxRef.current!;
      const source = ctx.createMediaStreamSource(stream);
      source.connect(analyserRef.current!);
      sourceRef.current = source as any;
      draw();
      setIsProcessing(true);
    } catch (err) {
      setError("Microphone access denied. Please check system permissions.");
      console.error("Mic access denied", err);
    }
  };

  const analyzeSpotify = () => {
    // Enhanced regex to capture Spotify IDs from various link formats
    const trackRegex = /track\/([a-zA-Z0-9]{22})/;
    const uriRegex = /spotify:track:([a-zA-Z0-9]{22})/;
    const match = spotifyLink.match(trackRegex) || spotifyLink.match(uriRegex);

    if (match && match[1]) {
      setActiveSpotifyId(match[1]);
      setError(null);
      stopAll();
      setIsProcessing(true);
      drawSpotifySim();
    } else {
      setError("Failed to resolve link. Please use a valid Spotify track URL.");
      setIsProcessing(false);
      setActiveSpotifyId(null);
    }
  };

  const getThemeColors = () => {
    const style = getComputedStyle(document.body);
    return {
      bg: style.getPropertyValue('--bg').trim(),
      fg: style.getPropertyValue('--fg').trim()
    };
  };

  const draw = () => {
    if (!canvasRef.current || !analyserRef.current) return;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d')!;
    const bufferLength = analyserRef.current.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);

    const renderFrame = () => {
      animationIdRef.current = requestAnimationFrame(renderFrame);
      analyserRef.current!.getByteTimeDomainData(dataArray);

      const colors = getThemeColors();

      ctx.globalAlpha = 0.2;
      ctx.fillStyle = colors.bg;
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.globalAlpha = 1.0;

      ctx.lineWidth = 4;
      ctx.strokeStyle = colors.fg;
      ctx.shadowBlur = 10;
      ctx.shadowColor = colors.fg;
      ctx.lineJoin = 'round';
      ctx.lineCap = 'round';

      ctx.beginPath();
      const sliceWidth = canvas.width / bufferLength;
      let x = 0;

      for (let i = 0; i < bufferLength; i++) {
        const v = dataArray[i] / 128.0;
        const y = v * (canvas.height / 2);
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
        x += sliceWidth;
      }

      ctx.lineTo(canvas.width, canvas.height / 2);
      ctx.stroke();
      ctx.shadowBlur = 0;
    };
    renderFrame();
  };

  const drawSpotifySim = () => {
    if (!canvasRef.current) return;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d')!;
    let offset = 0;

    const renderFrame = () => {
      animationIdRef.current = requestAnimationFrame(renderFrame);
      const colors = getThemeColors();

      ctx.globalAlpha = 0.15;
      ctx.fillStyle = colors.bg;
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.globalAlpha = 1.0;

      ctx.lineWidth = 3;
      ctx.strokeStyle = colors.fg;
      ctx.shadowBlur = 20;
      ctx.shadowColor = colors.fg;

      for (let j = 0; j < 3; j++) {
        ctx.beginPath();
        ctx.globalAlpha = 1 - (j * 0.3);
        for (let i = 0; i < canvas.width; i += 5) {
          const drift = Math.sin(offset * 0.5) * 10;
          const noise = Math.sin(i * 0.01 + offset * (j + 1)) * 70 + 
                        Math.cos(i * 0.02 - offset * 0.7) * 40 + 
                        Math.sin(i * 0.04 + drift) * 20;
          const y = (canvas.height / 2) + noise * (amp + 0.5);
          if (i === 0) ctx.moveTo(i, y);
          else ctx.lineTo(i, y);
        }
        ctx.stroke();
      }

      offset += 0.2; // Faster, more rhythmic offset
      ctx.globalAlpha = 1;
      ctx.shadowBlur = 0;
    };
    renderFrame();
  };

  useEffect(() => {
    if (isProcessing && mode === 'SYNTH' && sourceRef.current && (sourceRef.current as OscillatorNode).frequency) {
      (sourceRef.current as OscillatorNode).frequency.setTargetAtTime(freq, audioCtxRef.current!.currentTime, 0.1);
      (sourceRef.current as OscillatorNode).type = type;
      gainRef.current!.gain.setTargetAtTime(amp * 0.1, audioCtxRef.current!.currentTime, 0.1);
    }
  }, [freq, amp, type]);

  useEffect(() => {
    return () => stopAll();
  }, []);

  return (
    <div className="p-8 md:p-12 flex flex-col gap-8 bg-bg h-full">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div className="flex items-center gap-4">
            <Activity className="text-fg animate-pulse" />
            <div>
                <h3 className="font-serif text-3xl italic mb-1">Spectral_Architect</h3>
                <p className="font-mono text-[10px] uppercase opacity-40 tracking-widest">Neural Signal Processor</p>
            </div>
        </div>
        <div className="flex gap-2">
            {['SYNTH', 'MIC', 'SPOTIFY'].map((m: any) => (
                <button 
                    key={m}
                    onClick={() => { setMode(m); stopAll(); setActiveSpotifyId(null); }}
                    className={`px-4 py-2 border font-mono text-[10px] uppercase font-bold transition-all ${mode === m ? 'bg-fg text-bg border-fg' : 'border-fg/20 opacity-40 hover:opacity-100'}`}
                >
                    {m}
                </button>
            ))}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        <div className="lg:col-span-1 space-y-6 bg-fg/5 p-6 border border-fg/10">
          <AnimatePresence mode="wait">
            {mode === 'SYNTH' && (
              <motion.div key="synth" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="space-y-6">
                <div className="space-y-3">
                   <div className="flex justify-between font-mono text-[9px] uppercase opacity-60"><span>Freq</span><span>{freq}Hz</span></div>
                   <input type="range" min="20" max="1500" value={freq} onChange={(e) => setFreq(parseInt(e.target.value))} className="w-full accent-fg h-1 appearance-none bg-fg/10" />
                </div>
                <div className="space-y-3">
                   <div className="flex justify-between font-mono text-[9px] uppercase opacity-60"><span>Amp</span><span>{(amp*100).toFixed(0)}%</span></div>
                   <input type="range" min="0" max="1" step="0.01" value={amp} onChange={(e) => setAmp(parseFloat(e.target.value))} className="w-full accent-fg h-1 appearance-none bg-fg/10" />
                </div>
                <div className="grid grid-cols-2 gap-2">
                    {['sine', 'square', 'sawtooth', 'triangle'].map((t: any) => (
                        <button key={t} onClick={() => setType(t)} className={`p-2 border font-mono text-[8px] uppercase ${type === t ? 'bg-fg text-bg' : 'border-fg/20'}`}>{t}</button>
                    ))}
                </div>
                <button onClick={isProcessing ? stopAll : startSynth} className={`w-full py-4 border-2 border-fg font-mono text-xs font-bold uppercase ${isProcessing ? 'bg-fg text-bg' : ''}`}>
                    {isProcessing ? "Terminate Feed" : "Ignite Engine"}
                </button>
              </motion.div>
            )}

            {mode === 'MIC' && (
              <motion.div key="mic" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="space-y-6">
                <div className="p-8 border-2 border-fg/20 bg-fg/5 text-center flex flex-col items-center justify-center min-h-[150px]">
                    <Mic className={`mb-4 ${isProcessing ? 'text-fg animate-bounce' : 'opacity-20'}`} size={40} />
                    <p className="font-mono text-[10px] uppercase opacity-60 tracking-wider">Acoustic Resonance Mode</p>
                </div>
                {error && <div className="p-3 bg-red-500/10 border border-red-500/20 text-red-500 font-mono text-[9px] flex items-center gap-2"><AlertCircle size={14}/>{error}</div>}
                <button onClick={isProcessing ? stopAll : startMic} className={`w-full py-4 border-2 border-fg font-mono text-xs font-bold uppercase ${isProcessing ? 'bg-fg text-bg' : ''}`}>
                    {isProcessing ? <MicOff size={14} className="inline mr-2"/> : <Mic size={14} className="inline mr-2"/>}
                    {isProcessing ? "Disable Mic" : "Initialize Capture"}
                </button>
              </motion.div>
            )}

            {mode === 'SPOTIFY' && (
              <motion.div key="spotify" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="space-y-6 flex flex-col h-full">
                <div className="space-y-4">
                    <label className="font-mono text-[10px] uppercase opacity-60 block tracking-widest">Spotify Source Link</label>
                    <div className="flex border-2 border-fg overflow-hidden min-w-0 bg-bg">
                        <div className="p-2 border-r-2 border-fg bg-fg/5 shrink-0"><LinkIcon size={16}/></div>
                        <input 
                            type="text" 
                            placeholder="Paste track URL..."
                            value={spotifyLink}
                            onChange={(e) => { setSpotifyLink(e.target.value); setError(null); }}
                            className="bg-transparent flex-1 p-3 font-mono text-[11px] outline-none min-w-0 truncate"
                        />
                    </div>
                </div>

                {activeSpotifyId ? (
                  <div className="w-full grow min-h-[300px] border-2 border-fg shadow-[8px_8px_0px_0px_var(--fg)] bg-black overflow-hidden group">
                    <iframe 
                      src={`https://open.spotify.com/embed/track/${activeSpotifyId}?utm_source=generator&theme=0`} 
                      width="100%" 
                      height="100%" 
                      frameBorder="0" 
                      allow="autoplay; clipboard-write; encrypted-media; fullscreen; picture-in-picture" 
                      loading="lazy"
                      className="grayscale group-hover:grayscale-0 transition-all duration-700"
                    ></iframe>
                  </div>
                ) : (
                  <div className="w-full grow min-h-[300px] border-2 border-fg border-dashed flex flex-col items-center justify-center p-8 text-center bg-fg/5 opacity-40">
                      <Music size={40} className="mb-4" />
                      <p className="font-mono text-[10px] uppercase">Link Required for Preview</p>
                  </div>
                )}

                {error && <div className="p-4 bg-red-500/10 border border-red-500/20 text-red-500 font-mono text-[9px] flex items-center gap-2 leading-tight"><AlertCircle size={18} className="shrink-0"/>{error}</div>}

                <div className="flex items-center gap-3 px-2">
                    <Radio className={`shrink-0 ${isProcessing ? 'animate-spin text-fg' : 'opacity-20'}`} size={20} />
                    <span className="font-mono text-[9px] uppercase font-bold opacity-30 tracking-widest">{isProcessing ? "SIM_PROBE_ACTIVE" : "SIM_IDLE"}</span>
                </div>

                <button onClick={analyzeSpotify} className="w-full py-5 border-2 border-fg font-mono text-xs font-bold uppercase hover:bg-fg hover:text-bg transition-all tracking-widest shadow-[4px_4px_0px_0px_var(--fg)] hover:shadow-none translate-x-[-2px] translate-y-[-2px] hover:translate-x-0 hover:translate-y-0">
                    {activeSpotifyId ? "Refresh Link" : "Initialize Link"}
                </button>
              </motion.div>
            )}
          </AnimatePresence>
        </div>

        <div className="lg:col-span-3 border border-fg bg-bg relative flex flex-col overflow-hidden min-h-[500px]">
            <div className="absolute inset-0 opacity-[0.05] pointer-events-none" style={{ 
                backgroundImage: 'linear-gradient(to right, currentColor 1px, transparent 1px), linear-gradient(to bottom, currentColor 1px, transparent 1px)', 
                backgroundSize: '40px 40px' 
            }} />

            <div className="p-5 border-b border-fg bg-fg/5 flex justify-between font-mono text-[10px] uppercase tracking-tighter opacity-50 z-10">
                <div className="flex gap-6">
                    <span className="flex items-center gap-2"><Cpu size={12}/> SOURCE: {mode}</span>
                    <span>BUFFER_DEPTH: 2048 SAMPLES</span>
                </div>
                <div className="flex items-center gap-2">
                    <div className={`w-2 h-2 rounded-full ${isProcessing ? 'bg-fg animate-ping' : 'bg-fg/20'}`} />
                    <span>LITERAL_FEED_SYNC</span>
                </div>
            </div>

            <div className="flex-1 relative p-4 flex items-center justify-center">
                <canvas 
                    ref={canvasRef} 
                    width={1400} 
                    height={600} 
                    className="w-full h-full object-contain cursor-none block"
                />
                {!isProcessing && (
                    <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                        <span className="font-mono text-xs uppercase tracking-[2em] opacity-10 animate-pulse">Awaiting Signal...</span>
                    </div>
                )}
            </div>

            <div className="p-5 border-t border-fg bg-fg/5 flex justify-between font-mono text-[9px] uppercase opacity-40 z-10">
                <span>Phase_Shift_Control: 0.00ms</span>
                <span className="animate-pulse">{isProcessing ? "Deconstructing Harmonics..." : "Architecture Idle"}</span>
            </div>
        </div>
      </div>
    </div>
  );
};

// --- TIC TAC TOE ---
const TicTacToe = () => {
  const [board, setBoard] = useState<(string | null)[]>(Array(9).fill(null));
  const [xIsNext, setXIsNext] = useState(true);
  const [winner, setWinner] = useState<string | null>(null);

  const calculateWinner = (squares: (string | null)[]) => {
    const lines = [
      [0, 1, 2], [3, 4, 5], [6, 7, 8],
      [0, 3, 6], [1, 4, 7], [2, 5, 8],
      [0, 4, 8], [2, 4, 6],
    ];
    for (let i = 0; i < lines.length; i++) {
      const [a, b, c] = lines[i];
      if (squares[a] && squares[a] === squares[b] && squares[a] === squares[c]) {
        return squares[a];
      }
    }
    return null;
  };

  const handleClick = (i: number) => {
    if (winner || board[i]) return;
    const newBoard = board.slice();
    newBoard[i] = xIsNext ? 'X' : 'O';
    setBoard(newBoard);
    setXIsNext(!xIsNext);
    const win = calculateWinner(newBoard);
    if (win) setWinner(win);
    else if (!newBoard.includes(null)) setWinner('Draw');
  };

  const reset = () => {
    setBoard(Array(9).fill(null));
    setXIsNext(true);
    setWinner(null);
  };

  return (
    <div className="p-8 flex flex-col items-center justify-center h-full bg-bg">
      <div className="mb-8 text-center">
        <h3 className="font-serif text-3xl mb-2 italic">Tic_Tac_Toe.exe</h3>
        <p className="font-mono text-xs opacity-50 uppercase tracking-[0.2em]">
          {winner ? (winner === 'Draw' ? "STATUS: STALEMATE" : `WINNER: ${winner}`) : `ACTIVE TURN: ${xIsNext ? 'X' : 'O'}`}
        </p>
      </div>

      <div className="grid grid-cols-3 gap-2 border-2 border-fg p-2 shadow-[10px_10px_0px_0px_var(--fg)] bg-fg/5">
        {board.map((cell, i) => (
          <button
            key={i}
            onClick={() => handleClick(i)}
            className="w-20 h-20 md:w-24 md:h-24 border border-fg/20 flex items-center justify-center hover:bg-fg/10 transition-colors bg-bg"
          >
            {cell === 'X' && <XIcon size={40} className="text-fg" />}
            {cell === 'O' && <Circle size={40} className="text-fg" />}
          </button>
        ))}
      </div>

      <button
        onClick={reset}
        className="mt-10 px-12 py-3 border-2 border-fg font-mono text-[10px] font-bold uppercase hover:bg-fg hover:text-bg transition-all tracking-widest"
      >
        Reboot Match
      </button>
    </div>
  );
};

// --- MINI DAW ---
const MiniDAW = () => {
  const STEPS = 16;
  const TRACKS = 8;
  const TRACK_TYPES = [
    { id: 'BD', name: 'Kick' },
    { id: 'SD', name: 'Clap' },
    { id: 'CH', name: 'Hi-Hat' },
    { id: 'OH', name: 'Open Hat' },
    { id: 'TM', name: 'Tom' },
    { id: 'PR', name: 'Perc' },
    { id: 'BS', name: 'Bass' },
    { id: 'LD', name: 'Lead' },
  ];

  const [grid, setGrid] = useState<boolean[][]>(Array(TRACKS).fill(null).map(() => Array(STEPS).fill(false)));
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentStep, setCurrentStep] = useState(-1);
  const [bpm, setBpm] = useState(128);
  const audioContextRef = useRef<AudioContext | null>(null);
  const timerRef = useRef<number | null>(null);

  useEffect(() => {
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
      if (audioContextRef.current) audioContextRef.current.close();
    };
  }, []);

  const initAudio = () => {
    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    if (audioContextRef.current.state === 'suspended') audioContextRef.current.resume();
  };

  const playSound = (trackIndex: number) => {
    const ctx = audioContextRef.current;
    if (!ctx) return;
    const t = ctx.currentTime;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.connect(gain);
    gain.connect(ctx.destination);

    switch (trackIndex) {
      case 0: osc.frequency.setValueAtTime(150, t); osc.frequency.exponentialRampToValueAtTime(0.01, t + 0.5); break;
      case 1: osc.type = 'square'; gain.gain.setValueAtTime(0.1, t); break;
      default: osc.frequency.setValueAtTime(200 + (trackIndex * 100), t); break;
    }
    gain.gain.exponentialRampToValueAtTime(0.01, t + 0.3);
    osc.start(t); osc.stop(t + 0.3);
  };

  const togglePlay = () => {
    if (isPlaying) {
      setIsPlaying(false);
      setCurrentStep(-1);
      if (timerRef.current) clearInterval(timerRef.current);
    } else {
      initAudio();
      setIsPlaying(true);
      setCurrentStep(0);
      const interval = (60 / bpm) * 1000 / 4;
      timerRef.current = window.setInterval(() => {
        setCurrentStep(prev => {
          const next = (prev + 1) % STEPS;
          grid.forEach((trackSteps, idx) => {
            if (trackSteps[next]) playSound(idx);
          });
          return next;
        });
      }, interval);
    }
  };

  return (
    <div className="w-full h-full flex flex-col bg-bg text-fg overflow-hidden">
      <div className="h-12 bg-fg text-bg flex items-center justify-between px-4 shrink-0">
        <button onClick={togglePlay} className={`px-4 py-1 border border-bg rounded text-xs font-bold transition-all ${isPlaying ? 'bg-bg text-fg scale-95' : 'hover:scale-105'}`}>
          {isPlaying ? <Square size={12} fill="currentColor" /> : <Play size={12} fill="currentColor" />}
        </button>
        <div className="text-[10px] font-mono uppercase font-bold tracking-widest">Clock Speed: {bpm} BPM</div>
      </div>
      <div className="flex-1 flex overflow-hidden">
        <div className="w-32 border-r border-fg shrink-0 bg-fg/5">
          {TRACK_TYPES.map((t, i) => (
            <div key={i} className="h-12 border-b border-fg/10 px-4 flex items-center font-mono text-[9px] uppercase font-bold opacity-60">{t.name}</div>
          ))}
        </div>
        <div className="flex-1 overflow-x-auto custom-scrollbar">
          <div className="flex-1 flex overflow-hidden">
            <div className="flex flex-col min-w-max">
              {grid.map((track, trackIdx) => (
                <div key={trackIdx} className="h-12 border-b border-fg/10 flex">
                  {track.map((active, stepIdx) => (
                    <button
                      key={stepIdx}
                      onClick={() => {
                        const newGrid = [...grid];
                        newGrid[trackIdx][stepIdx] = !active;
                        setGrid(newGrid);
                      }}
                      className={`w-12 border-r border-fg/10 transition-all ${active ? 'bg-fg scale-90 rounded-sm' : 'hover:bg-fg/5'} ${currentStep === stepIdx ? 'ring-inset ring-2 ring-fg/20' : ''}`}
                    />
                  ))}
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

