    <section id="fun" className="grid grid-cols-1 md:grid-cols-4 bg-bg">
      <div className="p-8 border-b md:border-b-0 md:border-r border-fg flex items-center justify-center md:justify-start">
         <h2 className="text-3xl font-serif">Playground</h2>
      </div>
      <div className="md:col-span-3 grid grid-cols-1 md:grid-cols-4">
        {cards.map((card) => (
          <button
            key={card.id}
            onClick={() => setActiveGame(card.id)}
            className="aspect-square flex flex-col items-center justify-center gap-4 border-r border-b border-fg hover-invert group last:border-r-0"
          >
             <div className="group-hover:scale-110 transition-transform duration-300">{card.icon}</div>
             <span className="font-mono text-[10px] uppercase tracking-widest font-bold">{card.title}</span>
          </button>
        ))}
      </div>
      <AnimatePresence>
        {activeGame && (
          <Modal isOpen={!!activeGame} onClose={() => setActiveGame(null)} title={cards.find(c => c.id === activeGame)?.title || ''}>
            {activeGame === 'tictactoe' && <TicTacToe />}
            {activeGame === 'pixelpad' && <PixelGrid />}
            {activeGame === 'minidaw' && <MiniDAW />}
            {activeGame === 'waves' && <WaveformArchitect />}
          </Modal>
        )}
      </AnimatePresence>
    </section>
  );
};

