// --- WAVEFORM ARCHITECT (OSCILLOSCOPE) ---
const WaveformArchitect = () => {
  const [mode, setMode] = useState<'SYNTH' | 'MIC' | 'SPOTIFY'>('SYNTH');
  const [freq, setFreq] = useState(440);
  const [amp, setAmp] = useState(0.5);
  const [type, setType] = useState<OscillatorType>('sine');
  const [spotifyLink, setSpotifyLink] = useState('');
  const [activeSpotifyId, setActiveSpotifyId] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const canvasRef = useRef<HTMLCanvasElement>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const sourceRef = useRef<MediaStreamAudioSourceNode | OscillatorNode | null>(null);
  const gainRef = useRef<GainNode | null>(null);
  const animationIdRef = useRef<number | null>(null);

  const initAudio = () => {
    if (!audioCtxRef.current) {
      audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    if (!analyserRef.current) {
      analyserRef.current = audioCtxRef.current.createAnalyser();
      analyserRef.current.fftSize = 2048;
    }
    if (audioCtxRef.current.state === 'suspended') {
      audioCtxRef.current.resume();
    }
  };

  const stopAll = () => {
    setError(null);
    if (sourceRef.current) {
      try { (sourceRef.current as any).stop(); } catch(e) {}
      sourceRef.current.disconnect();
    }
    if (gainRef.current) gainRef.current.disconnect();
    if (animationIdRef.current) cancelAnimationFrame(animationIdRef.current);
    setIsProcessing(false);
  };

  const startSynth = () => {
    initAudio();
    stopAll();
    const ctx = audioCtxRef.current!;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();

    osc.type = type;
    osc.frequency.setValueAtTime(freq, ctx.currentTime);
    gain.gain.setValueAtTime(amp * 0.1, ctx.currentTime);

    osc.connect(gain);
    gain.connect(analyserRef.current!);
    gain.connect(ctx.destination);

    osc.start();
    sourceRef.current = osc;
    gainRef.current = gain;
    draw();
    setIsProcessing(true);
  };

  const startMic = async () => {
    initAudio();
    stopAll();
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const ctx = audioCtxRef.current!;
      const source = ctx.createMediaStreamSource(stream);
      source.connect(analyserRef.current!);
      sourceRef.current = source as any;
      draw();
      setIsProcessing(true);
    } catch (err) {
      setError("Microphone access denied. Please check system permissions.");
      console.error("Mic access denied", err);
    }
  };

  const analyzeSpotify = () => {
    // Robust parsing for different Spotify URL types
    const trackRegex = /track\/([a-zA-Z0-9]{22})/;
    const uriRegex = /spotify:track:([a-zA-Z0-9]{22})/;
    const match = spotifyLink.match(trackRegex) || spotifyLink.match(uriRegex);

    if (match && match[1]) {
      setActiveSpotifyId(match[1]);
      setError(null);
      stopAll();
      setIsProcessing(true);
      drawSpotifySim();
    } else {
      setError("Invalid Spotify Link. Paste track URL (open.spotify.com/track/...)");
      setIsProcessing(false);
      setActiveSpotifyId(null);
    }
  };

  const getThemeColors = () => {
    const style = getComputedStyle(document.body);
    return {
      bg: style.getPropertyValue('--bg').trim(),
      fg: style.getPropertyValue('--fg').trim()
    };
  };

  const draw = () => {
    if (!canvasRef.current || !analyserRef.current) return;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d')!;
    const bufferLength = analyserRef.current.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);

    const renderFrame = () => {
      animationIdRef.current = requestAnimationFrame(renderFrame);
      analyserRef.current!.getByteTimeDomainData(dataArray);

      const colors = getThemeColors();

      ctx.globalAlpha = 0.2;
      ctx.fillStyle = colors.bg;
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.globalAlpha = 1.0;

      ctx.lineWidth = 4;
      ctx.strokeStyle = colors.fg;
      ctx.shadowBlur = 10;
      ctx.shadowColor = colors.fg;
      ctx.lineJoin = 'round';
      ctx.lineCap = 'round';

      ctx.beginPath();
      const sliceWidth = canvas.width / bufferLength;
      let x = 0;

      for (let i = 0; i < bufferLength; i++) {
        const v = dataArray[i] / 128.0;
        const y = v * (canvas.height / 2);
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
        x += sliceWidth;
      }

      ctx.lineTo(canvas.width, canvas.height / 2);
      ctx.stroke();
      ctx.shadowBlur = 0;
    };
    renderFrame();
  };

  const drawSpotifySim = () => {
    if (!canvasRef.current) return;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d')!;
    let offset = 0;

    const renderFrame = () => {
      animationIdRef.current = requestAnimationFrame(renderFrame);
      const colors = getThemeColors();

      ctx.globalAlpha = 0.15;
      ctx.fillStyle = colors.bg;
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.globalAlpha = 1.0;

      ctx.lineWidth = 2.5;
      ctx.strokeStyle = colors.fg;
      ctx.shadowBlur = 15;
      ctx.shadowColor = colors.fg;

      // Draw multi-layered "Neural Harmonic" simulation
      for (let j = 0; j < 3; j++) {
        ctx.beginPath();
        ctx.globalAlpha = 1 - (j * 0.3);
        for (let i = 0; i < canvas.width; i += 6) {
          const freqMod = 0.005 + (j * 0.002);
          const noise = Math.sin(i * freqMod + offset * (j + 1)) * 60 + 
                        Math.cos(i * (freqMod * 2) - offset * 0.5) * 40 + 
                        Math.sin(i * 0.02 + offset * 2) * 20;

          const y = (canvas.height / 2) + noise * (amp + 0.5);
          if (i === 0) ctx.moveTo(i, y);
          else ctx.lineTo(i, y);
        }
        ctx.stroke();
      }

      offset += 0.15;
      ctx.globalAlpha = 1;
      ctx.shadowBlur = 0;
    };
    renderFrame();
  };

  useEffect(() => {
    if (isProcessing && mode === 'SYNTH' && sourceRef.current && (sourceRef.current as OscillatorNode).frequency) {
      (sourceRef.current as OscillatorNode).frequency.setTargetAtTime(freq, audioCtxRef.current!.currentTime, 0.1);
      (sourceRef.current as OscillatorNode).type = type;
      gainRef.current!.gain.setTargetAtTime(amp * 0.1, audioCtxRef.current!.currentTime, 0.1);
    }
  }, [freq, amp, type]);

  useEffect(() => {
    return () => stopAll();
  }, []);

  return (
    <div className="p-8 md:p-12 flex flex-col gap-8 bg-bg h-full">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div className="flex items-center gap-4">
            <Activity className="text-fg animate-pulse" />
            <div>
                <h3 className="font-serif text-3xl italic mb-1">Spectral_Architect</h3>
                <p className="font-mono text-[10px] uppercase opacity-40 tracking-widest">Neural Signal Processor</p>
            </div>
        </div>
        <div className="flex gap-2">
            {['SYNTH', 'MIC', 'SPOTIFY'].map((m: any) => (
                <button 
                    key={m}
                    onClick={() => { setMode(m); stopAll(); setActiveSpotifyId(null); }}
                    className={`px-4 py-2 border font-mono text-[10px] uppercase font-bold transition-all ${mode === m ? 'bg-fg text-bg border-fg' : 'border-fg/20 opacity-40 hover:opacity-100'}`}
                >
                    {m}
                </button>
            ))}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        <div className="lg:col-span-1 space-y-6 bg-fg/5 p-6 border border-fg/10 flex flex-col h-full">
          <AnimatePresence mode="wait">
            {mode === 'SYNTH' && (
              <motion.div key="synth" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="space-y-6">
                <div className="space-y-3">
                   <div className="flex justify-between font-mono text-[9px] uppercase opacity-60"><span>Freq</span><span>{freq}Hz</span></div>
                   <input type="range" min="20" max="1500" value={freq} onChange={(e) => setFreq(parseInt(e.target.value))} className="w-full accent-fg h-1 appearance-none bg-fg/10" />
                </div>
                <div className="space-y-3">
                   <div className="flex justify-between font-mono text-[9px] uppercase opacity-60"><span>Amp</span><span>{(amp*100).toFixed(0)}%</span></div>
                   <input type="range" min="0" max="1" step="0.01" value={amp} onChange={(e) => setAmp(parseFloat(e.target.value))} className="w-full accent-fg h-1 appearance-none bg-fg/10" />
                </div>
                <div className="grid grid-cols-2 gap-2">
                    {['sine', 'square', 'sawtooth', 'triangle'].map((t: any) => (
                        <button key={t} onClick={() => setType(t)} className={`p-2 border font-mono text-[8px] uppercase ${type === t ? 'bg-fg text-bg' : 'border-fg/20'}`}>{t}</button>
                    ))}
                </div>
                <button onClick={isProcessing ? stopAll : startSynth} className={`w-full py-4 border-2 border-fg font-mono text-xs font-bold uppercase ${isProcessing ? 'bg-fg text-bg' : ''}`}>
                    {isProcessing ? "Terminate Feed" : "Ignite Engine"}
                </button>
              </motion.div>
            )}

            {mode === 'MIC' && (
              <motion.div key="mic" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="space-y-6">
                <div className="p-8 border-2 border-fg/20 bg-fg/5 text-center flex flex-col items-center justify-center min-h-[150px]">
                    <Mic className={`mb-4 ${isProcessing ? 'text-fg animate-bounce' : 'opacity-20'}`} size={40} />
                    <p className="font-mono text-[10px] uppercase opacity-60 tracking-wider">Acoustic Resonance Mode</p>
                </div>
                {error && <div className="p-3 bg-red-500/10 border border-red-500/20 text-red-500 font-mono text-[9px] flex items-center gap-2 leading-tight"><AlertCircle size={14} className="shrink-0"/>{error}</div>}
                <button onClick={isProcessing ? stopAll : startMic} className={`w-full py-4 border-2 border-fg font-mono text-xs font-bold uppercase ${isProcessing ? 'bg-fg text-bg' : ''}`}>
                    {isProcessing ? "Disable Mic" : "Initialize Capture"}
                </button>
              </motion.div>
            )}

            {mode === 'SPOTIFY' && (
              <motion.div key="spotify" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="space-y-6 flex-1 flex flex-col">
                <div className="space-y-4">
                    <label className="font-mono text-[10px] uppercase opacity-60 block tracking-widest">Spotify Source Link</label>
                    <div className="flex border-2 border-fg overflow-hidden min-w-0 bg-bg">
