// --- TIC TAC TOE (WITH AI) ---
const TicTacToe = () => {
  const [board, setBoard] = useState<(string | null)[]>(Array(9).fill(null));
  const [xIsNext, setXIsNext] = useState(true);
  const [winner, setWinner] = useState<string | null>(null);
  const [vsAI, setVsAI] = useState(true);

  const calculateWinner = (squares: (string | null)[]) => {
    const lines = [
      [0, 1, 2], [3, 4, 5], [6, 7, 8],
      [0, 3, 6], [1, 4, 7], [2, 5, 8],
      [0, 4, 8], [2, 4, 6],
    ];
    for (let i = 0; i < lines.length; i++) {
      const [a, b, c] = lines[i];
      if (squares[a] && squares[a] === squares[b] && squares[a] === squares[c]) {
        return squares[a];
      }
    }
    return null;
  };

  const getBestMove = (squares: (string | null)[]) => {
    // Basic AI move logic
    const available = squares.map((v, i) => v === null ? i : null).filter(v => v !== null) as number[];
    if (available.length === 0) return null;

    // 1. Check if AI can win
    for (let move of available) {
      const copy = [...squares];
      copy[move] = 'O';
      if (calculateWinner(copy) === 'O') return move;
    }
    // 2. Check if player can win and block
    for (let move of available) {
      const copy = [...squares];
      copy[move] = 'X';
      if (calculateWinner(copy) === 'X') return move;
    }
    // 3. Random move
    return available[Math.floor(Math.random() * available.length)];
  };

  useEffect(() => {
    if (vsAI && !xIsNext && !winner) {
      const timer = setTimeout(() => {
        const move = getBestMove(board);
        if (move !== null) handleClick(move);
      }, 500);
      return () => clearTimeout(timer);
    }
  }, [xIsNext, board, vsAI, winner]);

  const handleClick = (i: number) => {
    if (winner || board[i]) return;
    const newBoard = board.slice();
    newBoard[i] = xIsNext ? 'X' : 'O';
    setBoard(newBoard);
    setXIsNext(!xIsNext);
    const win = calculateWinner(newBoard);
    if (win) setWinner(win);
    else if (!newBoard.includes(null)) setWinner('Draw');
  };

  const reset = () => {
    setBoard(Array(9).fill(null));
    setXIsNext(true);
    setWinner(null);
  };

  return (
    <div className="p-8 flex flex-col items-center justify-center h-full bg-bg">
      <div className="mb-8 text-center">
        <h3 className="font-serif text-3xl mb-2 italic">Tic_Tac_Toe.exe</h3>
        <div className="flex gap-4 justify-center mb-4">
           <button onClick={() => { setVsAI(false); reset(); }} className={`px-3 py-1 font-mono text-[9px] border ${!vsAI ? 'bg-fg text-bg' : 'border-fg opacity-40'}`}>
              <User size={12} className="inline mr-1" /> PVP
           </button>
           <button onClick={() => { setVsAI(true); reset(); }} className={`px-3 py-1 font-mono text-[9px] border ${vsAI ? 'bg-fg text-bg' : 'border-fg opacity-40'}`}>
              <Bot size={12} className="inline mr-1" /> VS_CPU
           </button>
        </div>
        <p className="font-mono text-xs opacity-50 uppercase tracking-[0.2em]">
          {winner ? (winner === 'Draw' ? "STATUS: STALEMATE" : `WINNER: ${winner}`) : `ACTIVE: ${xIsNext ? 'HUMAN (X)' : (vsAI ? 'CPU (O)' : 'FRIEND (O)')}`}
        </p>
      </div>

      <div className="grid grid-cols-3 gap-2 border-2 border-fg p-2 shadow-[10px_10px_0px_0px_var(--fg)] bg-fg/5">
        {board.map((cell, i) => (
          <button
            key={i}
            onClick={() => handleClick(i)}
            disabled={vsAI && !xIsNext}
            className="w-20 h-20 md:w-24 md:h-24 border border-fg/20 flex items-center justify-center hover:bg-fg/10 transition-colors bg-bg"
          >
            {cell === 'X' && <XIcon size={40} className="text-fg" />}
            {cell === 'O' && <Circle size={40} className="text-fg" />}
          </button>
        ))}
      </div>

      <button onClick={reset} className="mt-10 px-12 py-3 border-2 border-fg font-mono text-[10px] font-bold uppercase hover:bg-fg hover:text-bg transition-all tracking-widest">
        Reboot Match
      </button>
    </div>
  );
};

// --- MINI DAW (EXPANDED) ---
const MiniDAW = () => {
  const STEPS = 16;
  const TRACKS = 8;
  const SAMPLE_PACKS = {
    'CLASSIC': [150, 440, 880, 220, 660, 330, 110, 550],
    'BASS': [60, 80, 100, 120, 40, 70, 90, 110],
    'CHIP': [1000, 1200, 800, 1400, 600, 1800, 400, 2000]
  };

  const [grid, setGrid] = useState<boolean[][]>(Array(TRACKS).fill(null).map(() => Array(STEPS).fill(false)));
  const [trackSettings, setTrackSettings] = useState<{freq: number, type: OscillatorType}[]>(
    Array(TRACKS).fill(null).map((_, i) => ({ freq: SAMPLE_PACKS.CLASSIC[i], type: 'sine' }))
  );
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentStep, setCurrentStep] = useState(-1);
  const [bpm, setBpm] = useState(120);
  const [activePack, setActivePack] = useState<'CLASSIC' | 'BASS' | 'CHIP'>('CLASSIC');

  const audioContextRef = useRef<AudioContext | null>(null);
  const timerRef = useRef<number | null>(null);

  useEffect(() => {
    if (isPlaying && timerRef.current) {
      clearInterval(timerRef.current);
      startLoop();
    }
  }, [bpm]);

  const initAudio = () => {
    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    if (audioContextRef.current.state === 'suspended') audioContextRef.current.resume();
  };

  const applyPack = (packKey: keyof typeof SAMPLE_PACKS) => {
    setActivePack(packKey);
    setTrackSettings(prev => prev.map((s, i) => ({ ...s, freq: SAMPLE_PACKS[packKey][i] })));
  };

  const playSound = (trackIdx: number) => {
    const ctx = audioContextRef.current;
    if (!ctx) return;
    const { freq, type } = trackSettings[trackIdx];
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, ctx.currentTime);
    osc.connect(gain);
    gain.connect(ctx.destination);
    gain.gain.setValueAtTime(0.1, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.2);
    osc.start();
    osc.stop(ctx.currentTime + 0.2);
  };

  const startLoop = () => {
    const interval = (60 / bpm) * 1000 / 4;
    timerRef.current = window.setInterval(() => {
      setCurrentStep(prev => {
        const next = (prev + 1) % STEPS;
        grid.forEach((trackSteps, idx) => {
          if (trackSteps[next]) playSound(idx);
        });
        return next;
      });
    }, interval);
  };

  const togglePlay = () => {
    if (isPlaying) {
      setIsPlaying(false);
      setCurrentStep(-1);
      if (timerRef.current) clearInterval(timerRef.current);
    } else {
      initAudio();
      setIsPlaying(true);
      setCurrentStep(0);
      startLoop();
    }
  };

  return (
    <div className="w-full h-full flex flex-col bg-bg text-fg">
      <div className="h-14 border-b border-fg flex items-center justify-between px-6 shrink-0 bg-fg/5">
        <div className="flex items-center gap-6">
            <button onClick={togglePlay} className={`w-10 h-10 flex items-center justify-center border-2 border-fg rounded-full transition-all ${isPlaying ? 'bg-fg text-bg' : 'hover:bg-fg/10'}`}>
                {isPlaying ? <Square size={16} fill="currentColor" /> : <Play size={16} fill="currentColor" className="ml-1" />}
            </button>
            <div className="flex flex-col">
                <span className="font-mono text-[9px] uppercase opacity-40">Tempo Control</span>
                <div className="flex items-center gap-3">
                    <input type="range" min="60" max="200" value={bpm} onChange={(e) => setBpm(parseInt(e.target.value))} className="accent-fg w-32" />
                    <span className="font-mono text-xs font-bold">{bpm} BPM</span>
                </div>
            </div>
        </div>

        <div className="flex items-center gap-3">
            <span className="font-mono text-[9px] uppercase opacity-40">Sample Pack</span>
            {Object.keys(SAMPLE_PACKS).map((pk: any) => (
                <button key={pk} onClick={() => applyPack(pk)} className={`px-3 py-1 border font-mono text-[10px] uppercase transition-all ${activePack === pk ? 'bg-fg text-bg border-fg' : 'border-fg/20 hover:border-fg'}`}>
                    {pk}
                </button>
            ))}
        </div>
      </div>

      <div className="flex-1 flex overflow-hidden">
        <div className="w-48 border-r border-fg shrink-0 flex flex-col">
          {trackSettings.map((s, i) => (
            <div key={i} className="h-14 border-b border-fg/10 px-4 flex flex-col justify-center gap-1 bg-fg/5">
                <div className="flex justify-between items-center">
                    <span className="font-mono text-[10px] font-bold opacity-60">TRK_{i+1}</span>
                    <select value={s.type} onChange={(e) => {
                        const next = [...trackSettings];
                        next[i].type = e.target.value as OscillatorType;
                        setTrackSettings(next);
                    }} className="bg-transparent font-mono text-[8px] uppercase outline-none cursor-pointer border-b border-fg/20">
                        <option value="sine">Sine</option>
                        <option value="square">Square</option>
                        <option value="sawtooth">Saw</option>
                        <option value="triangle">Tri</option>
                    </select>
                </div>
                <input type="range" min="40" max="2000" value={s.freq} onChange={(e) => {
                    const next = [...trackSettings];
                    next[i].freq = parseInt(e.target.value);
                    setTrackSettings(next);
                }} className="w-full accent-fg h-1 appearance-none bg-fg/10" />
            </div>
          ))}
        </div>

        <div className="flex-1 overflow-x-auto custom-scrollbar">
          <div className="flex flex-col min-w-max">
            {grid.map((track, trackIdx) => (
              <div key={trackIdx} className="h-14 border-b border-fg/10 flex">
                {track.map((active, stepIdx) => (
                  <button
                    key={stepIdx}
                    onClick={() => {
                      const newGrid = [...grid];
                      newGrid[trackIdx][stepIdx] = !active;
                      setGrid(newGrid);
                    }}
                    className={`w-14 border-r border-fg/10 transition-all ${active ? 'bg-fg scale-90' : 'hover:bg-fg/5'} ${currentStep === stepIdx ? 'bg-fg/20' : ''} ${stepIdx % 4 === 0 ? 'border-l-2 border-fg/20' : ''}`}
                  />
                ))}
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

