                <Paintbrush size={16} />
             </button>
             <button onClick={() => setTool('ERASER')} className={`p-2 border ${tool === 'ERASER' ? 'bg-fg text-bg' : 'border-fg opacity-40'}`}>
                <Eraser size={16} />
             </button>
          </div>
      </div>

      <div 
        className={`grid grid-cols-16 gap-px bg-fg/10 border border-fg mb-8 shadow-[10px_10px_0px_0px_var(--fg)] ${tool === 'ERASER' ? 'cursor-alias' : 'cursor-crosshair'}`}
        style={{ gridTemplateColumns: 'repeat(16, minmax(0, 1fr))' }}
        onMouseDown={() => { isDragging.current = true; }}
