import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Play, Square, X, Music, Grid3X3, Circle, X as XIcon, Cpu, Zap, Activity, Waves, Mic, Link as LinkIcon, AlertCircle, Eraser, Paintbrush, User, Bot, SlidersHorizontal, Settings2, Volume2, RotateCcw, Save, Trash2, RefreshCw } from 'lucide-react';

// --- RECTANGULAR MODAL COMPONENT ---
interface ModalProps {
  isOpen: boolean;
  onClose: () => void;
  title: string;
  children: React.ReactNode;
}

const Modal: React.FC<ModalProps> = ({ isOpen, onClose, title, children }) => {
  if (!isOpen) return null;
  return (
    <div className="fixed inset-0 z-[150] flex items-center justify-center p-4 bg-fg/30 backdrop-blur-md">
      <motion.div 
        initial={{ opacity: 0, scale: 0.9, y: 20 }}
        animate={{ opacity: 1, scale: 1, y: 0 }}
        exit={{ opacity: 0, scale: 0.9, y: 20 }}
        className="w-full max-w-7xl bg-bg border-2 border-fg shadow-[16px_16px_0px_0px_var(--fg)] flex flex-col h-[85vh] text-fg overflow-hidden"
      >
        <div className="flex justify-between items-center p-4 border-b-2 border-fg bg-fg text-bg shrink-0">
          <div className="flex items-center gap-3">
            <div className="w-2 h-2 bg-bg rounded-full animate-pulse" />
            <span className="font-mono text-sm font-bold uppercase tracking-wider">Module // {title}</span>
          </div>
          <button onClick={onClose} className="hover:bg-bg hover:text-fg transition-colors p-1 border border-transparent hover:border-bg">
            <X size={20} />
          </button>
        </div>
        <div className="flex-1 overflow-hidden font-sans bg-bg relative">
          {children}
        </div>
      </motion.div>
    </div>
  );
};

// --- WAVEFORM ARCHITECT ---
const WaveformArchitect = () => {
  const [mode, setMode] = useState<'SYNTH' | 'MIC' | 'SPOTIFY'>('SYNTH');
  const [freq, setFreq] = useState(440);
  const [amp, setAmp] = useState(0.5);
  const [type, setType] = useState<OscillatorType>('sine');

  // Mic Recording State
  const [isRecording, setIsRecording] = useState(false);
  const [recordedBuffer, setRecordedBuffer] = useState<AudioBuffer | null>(null);
  const [isProcessing, setIsProcessing] = useState(false); // Playback status
  const [error, setError] = useState<string | null>(null);

  const canvasRef = useRef<HTMLCanvasElement>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const sourceRef = useRef<OscillatorNode | AudioBufferSourceNode | MediaStreamAudioSourceNode | null>(null);
  const gainRef = useRef<GainNode | null>(null);
  const animationIdRef = useRef<number | null>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const chunksRef = useRef<Blob[]>([]);

  const initAudio = () => {
    if (!audioCtxRef.current) {
      audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    if (!analyserRef.current) {
      analyserRef.current = audioCtxRef.current.createAnalyser();
      analyserRef.current.fftSize = 2048;
    }
    if (audioCtxRef.current.state === 'suspended') {
      audioCtxRef.current.resume();
    }
  };

  const stopAll = () => {
    setError(null);
    if (sourceRef.current) {
      try { sourceRef.current.disconnect(); } catch(e) {}
      try { (sourceRef.current as any).stop(); } catch(e) {}
      sourceRef.current = null;
    }
    if (gainRef.current) {
      gainRef.current.disconnect();
      gainRef.current = null;
    }
    if (animationIdRef.current) cancelAnimationFrame(animationIdRef.current);
    setIsProcessing(false);
  };

  const startSynth = () => {
    initAudio();
    stopAll();
    const ctx = audioCtxRef.current!;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();

    osc.type = type;
    osc.frequency.setValueAtTime(freq, ctx.currentTime);
    gain.gain.setValueAtTime(amp, ctx.currentTime);

    osc.connect(gain);
    gain.connect(analyserRef.current!);
    gain.connect(ctx.destination);

    osc.start();
    sourceRef.current = osc;
    gainRef.current = gain;
    draw();
    setIsProcessing(true);
  };

  const startMicRecording = async () => {
    initAudio();
    stopAll();
    setError(null);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const recorder = new MediaRecorder(stream);
      mediaRecorderRef.current = recorder;
      chunksRef.current = [];

      recorder.ondataavailable = (e) => {
        if (e.data.size > 0) chunksRef.current.push(e.data);
      };

      recorder.onstop = async () => {
        const blob = new Blob(chunksRef.current, { type: 'audio/ogg; codecs=opus' });
        const arrayBuffer = await blob.arrayBuffer();
        audioCtxRef.current?.decodeAudioData(arrayBuffer, (buffer) => {
          setRecordedBuffer(buffer);
        });
        stream.getTracks().forEach(track => track.stop());
      };

      recorder.start();
      setIsRecording(true);

      // Also visualize live mic feed
      const source = audioCtxRef.current!.createMediaStreamSource(stream);
      source.connect(analyserRef.current!);
      sourceRef.current = source;
      draw();
    } catch (err) {
      setError("Microphone access denied.");
    }
  };

  const stopMicRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
      stopAll();
    }
  };

  const playRecordedBuffer = () => {
    if (!recordedBuffer || !audioCtxRef.current) return;
    stopAll();
    const ctx = audioCtxRef.current;
    const source = ctx.createBufferSource();
    const gain = ctx.createGain();

    source.buffer = recordedBuffer;
    source.loop = true;

    // Use Frequency slider as PlaybackRate (0.1x to 4x)
    // Mapping 20-1500Hz range to 0.5-2.0x playback rate for intuitive manipulation
    const pRate = (freq / 440); 
    source.playbackRate.setValueAtTime(pRate, ctx.currentTime);
    gain.gain.setValueAtTime(amp, ctx.currentTime);

    source.connect(gain);
    gain.connect(analyserRef.current!);
    gain.connect(ctx.destination);

    source.start();
    sourceRef.current = source;
    gainRef.current = gain;
    draw();
    setIsProcessing(true);
  };

  // Update parameters in real-time
  useEffect(() => {
    if (isProcessing && audioCtxRef.current) {
      const ctx = audioCtxRef.current;
      if (sourceRef.current instanceof OscillatorNode) {
        sourceRef.current.frequency.setTargetAtTime(freq, ctx.currentTime, 0.05);
        sourceRef.current.type = type;
      } else if (sourceRef.current instanceof AudioBufferSourceNode) {
        // Map freq to playback rate for samples
        const pRate = (freq / 440);
        sourceRef.current.playbackRate.setTargetAtTime(pRate, ctx.currentTime, 0.05);
      }
      if (gainRef.current) {
        gainRef.current.gain.setTargetAtTime(amp, ctx.currentTime, 0.05);
      }
    }
  }, [freq, amp, type]);

  const draw = () => {
    if (!canvasRef.current || !analyserRef.current) return;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d')!;
    const bufferLength = analyserRef.current.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);

    const renderFrame = () => {
      animationIdRef.current = requestAnimationFrame(renderFrame);
      analyserRef.current!.getByteTimeDomainData(dataArray);
      const style = getComputedStyle(document.body);
      const bg = style.getPropertyValue('--bg').trim();
      const fg = style.getPropertyValue('--fg').trim();

      ctx.fillStyle = bg;
      ctx.globalAlpha = 0.2;
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.globalAlpha = 1.0;
      ctx.lineWidth = 3;
      ctx.strokeStyle = fg;
      ctx.beginPath();
      const sliceWidth = canvas.width / bufferLength;
      let x = 0;
      for (let i = 0; i < bufferLength; i++) {
        const v = dataArray[i] / 128.0;
        const y = v * (canvas.height / 2);
        if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
        x += sliceWidth;
      }
      ctx.lineTo(canvas.width, canvas.height / 2);
      ctx.stroke();
    };
    renderFrame();
  };

  useEffect(() => {
    return () => stopAll();
  }, []);

  return (
    <div className="h-full flex flex-col p-8 gap-8 overflow-y-auto">
      <div className="flex justify-between items-center border-b border-fg pb-6">
        <div className="flex items-center gap-4">
          <Activity className="animate-pulse" />
          <h3 className="font-serif text-3xl italic">Spectral Architect</h3>
        </div>
        <div className="flex gap-2">
          {['SYNTH', 'MIC', 'SPOTIFY'].map((m: any) => (
            <button key={m} onClick={() => { setMode(m); stopAll(); setRecordedBuffer(null); }} className={`px-4 py-2 border font-mono text-[10px] uppercase font-bold transition-all ${mode === m ? 'bg-fg text-bg' : 'border-fg/20 hover:border-fg'}`}>{m}</button>
          ))}
        </div>
      </div>

      <div className="flex-1 grid grid-cols-1 lg:grid-cols-12 gap-8">
        <div className="lg:col-span-4 bg-fg/5 p-6 border border-fg/10 space-y-6">
          <AnimatePresence mode="wait">
            {mode === 'SYNTH' && (
              <motion.div key="synth-ui" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="space-y-6">
                <div className="space-y-4">
                  <div className="space-y-2">
                    <div className="flex justify-between font-mono text-[9px] uppercase"><span>Frequency</span><span>{freq}Hz</span></div>
                    <input type="range" min="20" max="1500" value={freq} onChange={(e) => setFreq(parseInt(e.target.value))} className="w-full accent-fg h-1 appearance-none bg-fg/10" />
                  </div>
                  <div className="space-y-2">
                    <div className="flex justify-between font-mono text-[9px] uppercase"><span>Amplitude</span><span>{(amp * 100).toFixed(0)}%</span></div>
                    <input type="range" min="0" max="1" step="0.01" value={amp} onChange={(e) => setAmp(parseFloat(e.target.value))} className="w-full accent-fg h-1 appearance-none bg-fg/10" />
                  </div>
                </div>
                <div className="grid grid-cols-2 gap-2">
                  {['sine', 'square', 'sawtooth', 'triangle'].map((t: any) => (
                    <button key={t} onClick={() => setType(t)} className={`p-2 border font-mono text-[8px] uppercase ${type === t ? 'bg-fg text-bg' : 'border-fg/20'}`}>{t}</button>
                  ))}
                </div>
                <button onClick={isProcessing ? stopAll : startSynth} className={`w-full py-4 border-2 border-fg font-mono text-xs font-bold uppercase transition-all ${isProcessing ? 'bg-fg text-bg' : 'hover:bg-fg/5'}`}>
                  {isProcessing ? "Kill Engine" : "Ignite Synth"}
                </button>
              </motion.div>
            )}

            {mode === 'MIC' && (
              <motion.div key="mic-ui" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="space-y-6">
                <div className="p-8 border-2 border-fg border-dashed bg-fg/5 text-center flex flex-col items-center justify-center gap-4">
                  <Mic size={32} className={isRecording ? 'text-red-500 animate-pulse' : 'opacity-20'} />
                  <p className="font-mono text-[10px] uppercase opacity-60">Acoustic Sampler</p>
                </div>

                {!recordedBuffer ? (
                  <button 
                    onClick={isRecording ? stopMicRecording : startMicRecording} 
                    className={`w-full py-4 border-2 border-fg font-mono text-xs font-bold uppercase transition-all ${isRecording ? 'bg-red-500 text-white animate-pulse' : 'hover:bg-fg/5'}`}
                  >
                    {isRecording ? "Stop Capture" : "Initialize Capture"}
                  </button>
                ) : (
                  <div className="space-y-6">
                    <div className="space-y-4">
                      <div className="space-y-2">
                        <div className="flex justify-between font-mono text-[9px] uppercase"><span>Playback Rate (Freq)</span><span>{(freq/440).toFixed(2)}x</span></div>
                        <input type="range" min="20" max="1500" value={freq} onChange={(e) => setFreq(parseInt(e.target.value))} className="w-full accent-fg h-1 appearance-none bg-fg/10" />
                      </div>
                      <div className="space-y-2">
                        <div className="flex justify-between font-mono text-[9px] uppercase"><span>Amplitude</span><span>{(amp * 100).toFixed(0)}%</span></div>
                        <input type="range" min="0" max="1" step="0.01" value={amp} onChange={(e) => setAmp(parseFloat(e.target.value))} className="w-full accent-fg h-1 appearance-none bg-fg/10" />
                      </div>
                    </div>
                    <div className="flex gap-2">
                      <button onClick={isProcessing ? stopAll : playRecordedBuffer} className={`flex-1 py-4 border-2 border-fg font-mono text-xs font-bold uppercase ${isProcessing ? 'bg-fg text-bg' : 'hover:bg-fg/5'}`}>
                        {isProcessing ? "Stop" : "Play Loop"}
                      </button>
                      <button onClick={() => { stopAll(); setRecordedBuffer(null); }} className="p-4 border-2 border-fg hover:bg-fg/5 text-fg">
                        <Trash2 size={18} />
                      </button>
                    </div>
                  </div>
                )}
                {error && <div className="text-red-500 font-mono text-[10px] uppercase border border-red-500/20 p-2 bg-red-500/5">{error}</div>}
              </motion.div>
            )}

            {mode === 'SPOTIFY' && (
              <motion.div key="spotify-ui" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="p-8 text-center bg-fg/5 border border-fg/10">
                <Music size={40} className="mx-auto mb-4 opacity-20" />
                <p className="font-mono text-xs opacity-40 italic">Streaming integration pending structural approval.</p>
              </motion.div>
            )}
          </AnimatePresence>
        </div>

        <div className="lg:col-span-8 border border-fg relative flex flex-col bg-bg overflow-hidden shadow-[inner_0_2px_4px_rgba(0,0,0,0.1)]">
          <div className="absolute top-4 left-4 font-mono text-[8px] uppercase opacity-30 flex gap-4 pointer-events-none z-10">
            <span>RES: 2048 SAMPLES</span>
            <span>OSC: {isProcessing ? 'ACTIVE' : 'IDLE'}</span>
            <span>AMP: {(amp * 100).toFixed(0)}%</span>
          </div>
          <canvas ref={canvasRef} width={1200} height={600} className="w-full h-full object-cover cursor-crosshair" />
          {mode === 'SPOTIFY' && (
            <div className="absolute inset-0 flex items-center justify-center pointer-events-none z-20">
              <div className="border-[10px] border-red-600 p-8 transform -rotate-12 bg-bg/40 backdrop-blur-sm">
                <span className="text-red-600 font-mono text-6xl md:text-8xl font-black uppercase tracking-tighter animate-pulse">UNDER CONSTRUCTION</span>
              </div>
            </div>
          )}
          {!isProcessing && !isRecording && (
            <div className="absolute inset-0 flex items-center justify-center pointer-events-none opacity-10">
              <span className="font-mono text-xs uppercase tracking-[2em]">Signal Silenced</span>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

// --- MINI DAW (THE SEQUENCER) ---
const MiniDAW = () => {
  const STEPS = 32;
  const TRACKS = 8;
  const TRACK_NAMES = ['Kick', 'Snare', 'Hat', 'Perc', 'Bass', 'Lead', 'Pad', 'Fx'];
  const PACKS = {
    'NEURAL': [60, 180, 800, 400, 50, 440, 220, 1200],
    'PULSE': [40, 120, 1200, 600, 35, 330, 110, 1800],
    'GLITCH': [150, 250, 4000, 2000, 80, 880, 550, 3000]
  };

  const [grid, setGrid] = useState<boolean[][]>(Array(TRACKS).fill(null).map(() => Array(STEPS).fill(false)));
  const [trackSettings, setTrackSettings] = useState<{freq: number, type: OscillatorType}[]>(
    Array(TRACKS).fill(null).map((_, i) => ({ freq: PACKS.NEURAL[i], type: 'sine' }))
  );
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentStep, setCurrentStep] = useState(-1);
  const [bpm, setBpm] = useState(124);
  const [activePack, setActivePack] = useState<keyof typeof PACKS>('NEURAL');

  const audioCtx = useRef<AudioContext | null>(null);
  const timer = useRef<number | null>(null);

  const initAudio = () => {
    if (!audioCtx.current) audioCtx.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    if (audioCtx.current.state === 'suspended') audioCtx.current.resume();
  };

  const playSound = (idx: number) => {
    if (!audioCtx.current) return;
    const { freq, type } = trackSettings[idx];
    const osc = audioCtx.current.createOscillator();
    const gain = audioCtx.current.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, audioCtx.current.currentTime);
    osc.connect(gain);
    gain.connect(audioCtx.current.destination);
    gain.gain.setValueAtTime(0.1, audioCtx.current.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.current.currentTime + 0.15);
    osc.start();
    osc.stop(audioCtx.current.currentTime + 0.15);
  };

  useEffect(() => {
    if (isPlaying) {
      if (timer.current) clearInterval(timer.current);
      const interval = (60 / bpm) * 1000 / 4;
      timer.current = window.setInterval(() => {
        setCurrentStep(prev => {
          const next = (prev + 1) % STEPS;
          grid.forEach((track, i) => { if (track[next]) playSound(i); });
          return next;
        });
      }, interval);
    } else {
      if (timer.current) clearInterval(timer.current);
      setCurrentStep(-1);
    }
    return () => { if (timer.current) clearInterval(timer.current); };
  }, [isPlaying, bpm, grid, trackSettings]);

  const switchPack = (pack: keyof typeof PACKS) => {
    setActivePack(pack);
    setTrackSettings(prev => prev.map((s, i) => ({ ...s, freq: PACKS[pack][i] })));
  };

  return (
    <div className="h-full flex flex-col bg-bg">
      <div className="flex flex-wrap items-center justify-between p-4 border-b border-fg bg-fg/5">
        <div className="flex items-center gap-6">
          <button onClick={() => { initAudio(); setIsPlaying(!isPlaying); }} className={`w-12 h-12 rounded-full border-2 border-fg flex items-center justify-center transition-all ${isPlaying ? 'bg-fg text-bg' : 'hover:bg-fg/10'}`}>
            {isPlaying ? <Square size={18} fill="currentColor" /> : <Play size={20} fill="currentColor" className="ml-1" />}
          </button>
          <div className="flex flex-col">
            <span className="font-mono text-[9px] uppercase opacity-40">Global Tempo</span>
            <div className="flex items-center gap-3">
              <input type="range" min="40" max="220" value={bpm} onChange={(e) => setBpm(parseInt(e.target.value))} className="w-32 accent-fg" />
              <span className="font-mono text-sm font-bold w-16">{bpm} BPM</span>
            </div>
          </div>
        </div>
        <div className="flex gap-2">
           {Object.keys(PACKS).map((p: any) => (
             <button key={p} onClick={() => switchPack(p)} className={`px-4 py-2 border font-mono text-[10px] uppercase font-bold transition-all ${activePack === p ? 'bg-fg text-bg' : 'border-fg/20 hover:border-fg'}`}>{p}_CORE</button>
           ))}
        </div>
      </div>

      <div className="flex-1 flex overflow-hidden">
        <div className="w-56 border-r border-fg shrink-0 flex flex-col overflow-y-auto custom-scrollbar bg-fg/5">
           {TRACK_NAMES.map((name, i) => (
             <div key={i} className="h-16 border-b border-fg/10 px-4 flex flex-col justify-center gap-1">
                <div className="flex justify-between items-center mb-1">
                  <span className="font-mono text-[10px] font-bold opacity-60">{name.toUpperCase()}</span>
                  <select value={trackSettings[i].type} onChange={(e) => {
                    const next = [...trackSettings];
                    next[i].type = e.target.value as OscillatorType;
                    setTrackSettings(next);
                  }} className="bg-transparent font-mono text-[8px] uppercase outline-none cursor-pointer">
                    <option value="sine">Sine</option><option value="square">Square</option><option value="sawtooth">Saw</option><option value="triangle">Tri</option>
                  </select>
                </div>
                <input type="range" min="40" max="2000" value={trackSettings[i].freq} onChange={(e) => {
                  const next = [...trackSettings];
                  next[i].freq = parseInt(e.target.value);
                  setTrackSettings(next);
                }} className="w-full h-1 accent-fg bg-fg/10 appearance-none rounded" />
             </div>
           ))}
        </div>

        <div className="flex-1 overflow-auto custom-scrollbar relative">
          <div className="flex flex-col min-w-max">
            {grid.map((track, trackIdx) => (
              <div key={trackIdx} className="h-16 border-b border-fg/10 flex">
                {track.map((active, stepIdx) => (
                  <button
                    key={stepIdx}
                    onClick={() => {
                      const n = [...grid];
                      n[trackIdx][stepIdx] = !active;
                      setGrid(n);
                    }}
                    className={`w-12 md:w-16 border-r border-fg/10 transition-all relative ${active ? 'bg-fg scale-90 rounded' : 'hover:bg-fg/5'} ${stepIdx % 4 === 0 ? 'bg-fg/[0.03]' : ''}`}
                  >
                    {currentStep === stepIdx && (
                      <div className="absolute inset-0 bg-fg/20 animate-pulse pointer-events-none" />
                    )}
                  </button>
                ))}
              </div>
            ))}
          </div>
          <div 
            className="absolute top-0 bottom-0 w-[2px] bg-fg shadow-[0_0_10px_var(--fg)] z-10 transition-all duration-75 pointer-events-none"
            style={{ 
              left: currentStep === -1 ? -10 : `calc(${currentStep} * ${window.innerWidth < 768 ? '48px' : '64px'})`,
              display: isPlaying ? 'block' : 'none' 
            }}
          />
        </div>
      </div>
    </div>
  );
};

// --- TIC TAC TOE (VS AI) ---
const TicTacToe = () => {
  const [board, setBoard] = useState<(string | null)[]>(Array(9).fill(null));
  const [xIsNext, setXIsNext] = useState(true);
  const [winner, setWinner] = useState<string | null>(null);
  const [mode, setMode] = useState<'PVP' | 'AI'>('AI');

  const checkWinner = (sq: (string | null)[]) => {
    const lines = [[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]];
    for(let l of lines) if(sq[l[0]] && sq[l[0]] === sq[l[1]] && sq[l[0]] === sq[l[2]]) return sq[l[0]];
    return sq.includes(null) ? null : 'Draw';
  };

  const getBestMove = (sq: (string | null)[]) => {
    const avail = sq.map((v, i) => v === null ? i : null).filter(v => v !== null) as number[];
    if(avail.length === 0) return null;
    for(let m of avail) { const c = [...sq]; c[m] = 'O'; if(checkWinner(c) === 'O') return m; }
    for(let m of avail) { const c = [...sq]; c[m] = 'X'; if(checkWinner(c) === 'X') return m; }
    if(sq[4] === null) return 4;
    return avail[Math.floor(Math.random() * avail.length)];
  };

  useEffect(() => {
    if(mode === 'AI' && !xIsNext && !winner) {
      const timer = setTimeout(() => {
        const move = getBestMove(board);
        if(move !== null) makeMove(move);
      }, 600);
      return () => clearTimeout(timer);
    }
  }, [xIsNext, board, winner, mode]);

  const makeMove = (i: number) => {
    if(board[i] || winner) return;
    const n = [...board];
    n[i] = xIsNext ? 'X' : 'O';
    setBoard(n);
    setXIsNext(!xIsNext);
    setWinner(checkWinner(n));
  };

  const reset = () => { setBoard(Array(9).fill(null)); setXIsNext(true); setWinner(null); };

  return (
    <div className="h-full flex flex-col items-center justify-center p-8 bg-bg">
