                  </div>

                  {/* Label */}
                  <div className="h-[25%] flex items-center justify-center">
                    <p className="font-mono text-[9px] text-center leading-tight truncate px-1 uppercase tracking-tighter">
                      {photo.alt}
                    </p>
                  </div>
                </motion.div>
              );
            })}
