import React, { useState, useRef, useEffect } from 'react';
import { MessageSquare, X, Send } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { ChatMessage } from '../types';
import { sendMessageToGemini } from '../services/geminiService';

const ChatWidget: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'model', text: "System online. How can I assist?" }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isOpen]);

  const handleSend = async () => {
    if (!input.trim()) return;

    const userMessage: ChatMessage = { role: 'user', text: input };
    setMessages(prev => [...prev, userMessage]);
    setInput('');
    setIsLoading(true);

    try {
      const responseText = await sendMessageToGemini(input);
      const aiMessage: ChatMessage = { role: 'model', text: responseText };
      setMessages(prev => [...prev, aiMessage]);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'model', text: "Connection error." }]);
    } finally {
      setIsLoading(false);
    }
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  return (
    <>
      <div className="fixed bottom-6 right-6 z-[100]">
        <AnimatePresence>
          {isOpen && (
            <motion.div
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: 10 }}
              className="absolute bottom-16 right-0 w-[300px] md:w-[350px] h-[450px] bg-bg border-2 border-accent shadow-[4px_4px_0px_0px_var(--fg)] flex flex-col"
            >
              {/* Terminal Header */}
              <div className="px-3 py-2 border-b border-accent bg-accent text-bg flex justify-between items-center">
                <div className="flex items-center gap-2">
                  <div className="w-1.5 h-1.5 bg-bg rounded-full animate-pulse" />
                  <span className="font-mono text-xs uppercase font-bold tracking-widest">Terminal_Assistant</span>
                </div>
                <button 
                  onClick={() => setIsOpen(false)}
                  className="hover:bg-bg hover:text-accent transition-colors p-1"
                >
                  <X size={14} />
                </button>
              </div>

              {/* Log */}
              <div className="flex-1 overflow-y-auto p-4 space-y-4 font-mono text-sm">
                {messages.map((msg, idx) => (
                  <div key={idx} className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                    <span className="text-[10px] opacity-50 mb-1 uppercase font-bold tracking-tighter">{msg.role === 'user' ? 'User_Input' : 'System_Kernel'}</span>
                    <div className={`max-w-[90%] p-3 border ${
                      msg.role === 'user' 
                        ? 'bg-accent text-bg border-accent' 
                        : 'bg-bg text-fg border-fg/20'
                    } shadow-sm`}>
                      {msg.text}
                    </div>
                  </div>
                ))}
                {isLoading && (
                   <div className="text-xs animate-pulse text-accent font-bold">> Processing_Data...</div>
                )}
                <div ref={messagesEndRef} />
              </div>

              {/* Input Line */}
              <div className="p-3 border-t border-accent/20 flex gap-2 bg-accent/5">
                <span className="font-mono pt-2 text-accent font-black">></span>
                <textarea
                  value={input}
                  onChange={(e) => setInput(e.target.value)}
                  onKeyDown={handleKeyPress}
                  placeholder="Enter command..."
                  className="flex-1 bg-transparent border-none focus:ring-0 resize-none font-mono text-sm p-2 outline-none placeholder:text-accent/30"
                  rows={1}
                />
                <button
                  onClick={handleSend}
                  disabled={isLoading || !input.trim()}
                  className="p-2 hover:bg-accent hover:text-bg transition-all text-accent border border-transparent hover:border-accent"
                >
                  <Send size={16} />
                </button>
              </div>
            </motion.div>
          )}
        </AnimatePresence>

        <button
          onClick={() => setIsOpen(!isOpen)}
          className="bg-accent text-bg border-2 border-fg p-4 shadow-[4px_4px_0px_0px_var(--fg)] hover:shadow-none hover:translate-x-[2px] hover:translate-y-[2px] transition-all group"
        >
          {isOpen ? <X size={28} /> : <MessageSquare size={28} className="group-hover:rotate-12 transition-transform" />}
        </button>
      </div>
    </>
  );
};

