                           {isProcessing ? "STOP" : "PLAYBACK"}
                         </button>
                         <button onClick={() => { stopAll(); setRecordedBuffer(null); }} className="p-3 border-2 border-red-600 text-red-600 hover:bg-red-600 hover:text-white transition-colors"><Trash2 size={16}/></button>
