          <button onClick={() => setTool('ERASE')} className={`p-3 border-2 ${tool === 'ERASE' ? 'bg-fg text-bg border-fg' : 'border-fg/20 opacity-40 hover:opacity-100'}`}><Eraser size={20} /></button>
