              >
                {/* Index Column */}
                <div className="md:col-span-1 p-6 md:p-8 font-mono text-xs opacity-40 border-b md:border-b-0 md:border-r border-fg group-hover:border-bg group-hover:opacity-100 flex flex-col justify-between">
                  <span>{paddedIndex}</span>
                  <motion.div 
                    animate={{ rotate: 360 }}
                    transition={{ duration: 10, repeat: Infinity, ease: "linear" }}
                    className="w-4 h-4 border border-current opacity-20 hidden md:block"
                  />
                </div>

                {/* Title Column */}
                <div className="md:col-span-4 p-6 md:p-8 flex flex-col justify-center border-b md:border-b-0 md:border-r border-fg group-hover:border-bg">
                  <div className="flex items-center gap-4 mb-2">
