                   alt={hoveredProject.title} 
                   className="w-full h-full object-cover grayscale group-hover:grayscale-0"
                />
                {/* Visual HUD overlay */}
                <div className="absolute inset-0 border border-accent/20 flex flex-col justify-between p-3">
                   <div className="flex justify-between items-start">
                      <div className="flex gap-1">
                        <div className="w-1 h-1 bg-accent rounded-full animate-pulse" />
                        <div className="w-1 h-1 bg-accent rounded-full animate-pulse delay-75" />
                      </div>
                      <span className="font-mono text-[8px] text-accent font-bold">REC_ARTIFACT</span>
                   </div>
                   <div className="flex justify-between items-end">
                      <div className="font-mono text-[7px] text-accent/50 leading-none">
